const SPKMOD_AUTO_BANNED_BOTS_KEY = "spkmod-auto-banned-bots";
var lunAutoBannedLevel1s = new Set();
var lunLocalPendingBots = new Set();
var lunActiveBotWaveMinId = Infinity;
let lunBotSyncInFlight = false;
let lunPendingBotReportQueue = null;

function enqueuePendingBotReport(newBotNames, removeNames, allowPromoteCheck) {
	if (!lunPendingBotReportQueue) {
		lunPendingBotReportQueue = {
			bots: [],
			removeNames: new Set(),
			allowPromoteCheck: Boolean(allowPromoteCheck)
		};
	} else if (allowPromoteCheck) {
		lunPendingBotReportQueue.allowPromoteCheck = true;
	}
	if (Array.isArray(newBotNames)) {
		for (const item of newBotNames) lunPendingBotReportQueue.bots.push(item);
	}
	if (Array.isArray(removeNames)) {
		for (const name of removeNames) {
			if (typeof name === "string" && name.trim()) {
				lunPendingBotReportQueue.removeNames.add(name.trim().toLocaleLowerCase());
			}
		}
	}
}


function loadAutoBannedBotsFromStorage() {
	if (!window.localStorage) return;
	try {
		const raw = localStorage.getItem(SPKMOD_AUTO_BANNED_BOTS_KEY);
		if (!raw) return;
		const parsed = JSON.parse(raw);
		if (!Array.isArray(parsed)) return;
		for (const item of parsed) {
			if (typeof item !== "string") continue;
			const lower = item.trim().toLocaleLowerCase();
			if (lower && !lunKnownBotNameSet.has(lower)) {
				lunAutoBannedLevel1s.add(lower);
			}
		}
	} catch (_) {}
}

function saveAutoBannedBotsToStorage() {
	if (!window.localStorage) return;
	try {
		localStorage.setItem(SPKMOD_AUTO_BANNED_BOTS_KEY, JSON.stringify([...lunAutoBannedLevel1s]));
	} catch (_) {}
}

loadAutoBannedBotsFromStorage();

function getBotReporterAuth() {
	const username = (typeof gameState !== "undefined" && gameState)
		? String(gameState.myPlayerName || gameState.myStat?.name || "").trim()
		: "";
	const playerId = (typeof gameState !== "undefined" && gameState && gameState.myPlayerId != null)
		? String(gameState.myPlayerId).trim()
		: "";
	const level = (typeof gameState !== "undefined" && gameState && gameState.myStat && typeof gameState.myStat.level === "number")
		? gameState.myStat.level
		: Number(gameState?.myStat?.level || 0);
	const authorized = Boolean(username && username !== "Anonymous" && playerId && Number.isFinite(level) && level >= 5);
	return { authorized, username, playerId, level };
}

function applyServerBotList(serverBots, allowPromoteCheck = true) {
	if (!Array.isArray(serverBots)) return;
	const nextSet = new Set();
	for (const name of serverBots) {
		if (typeof name !== "string") continue;
		const lower = name.trim().toLocaleLowerCase();
		if (lower && !lunKnownBotNameSet.has(lower)) {
			nextSet.add(lower);
		}
	}
	for (const pending of lunLocalPendingBots) {
		if (!lunKnownBotNameSet.has(pending)) {
			nextSet.add(pending);
		}
	}
	lunAutoBannedLevel1s = nextSet;
	saveAutoBannedBotsToStorage();

	if (allowPromoteCheck && typeof gameState !== "undefined" && gameState?.remotePlayers?.remotePlayers instanceof Map) {
		const promoted = [];
		for (const player of gameState.remotePlayers.remotePlayers.values()) {
			const lower = (player?.info?.name || "").trim().toLocaleLowerCase();
			const lvl = Number(player?.info?.level || 0);
			if (lower && lvl > 3 && !lunKnownBotNameSet.has(lower) && lunAutoBannedLevel1s.has(lower)) {
				lunAutoBannedLevel1s.delete(lower);
				lunLocalPendingBots.delete(lower);
				promoted.push(lower);
			}
		}
		if (promoted.length > 0) {
			saveAutoBannedBotsToStorage();
			reportBotsToServer([], promoted, false);
		}
	}

	if (typeof updateKnownBotVisibility === "function") {
		updateKnownBotVisibility();
	}
}

async function fetchRemoteBotList() {
	if (lunBotSyncInFlight) return;
	if (window.spkmodServerHealth && !window.spkmodServerHealth.isAvailable()) return;
	lunBotSyncInFlight = true;
	try {
		const safeFetch = window.spkmodSafeFetch || window.fetch;
		const res = await safeFetch(`${SPKMOD_SERVER_URL}/api/bots/list`, {}, 5000);
		if (!res.ok) throw new Error(`HTTP ${res.status}`);
		const data = await res.json();
		if (window.spkmodServerHealth) window.spkmodServerHealth.recordSuccess();
		if (data && data.success && Array.isArray(data.bots)) {
			applyServerBotList(data.bots, true);
		}
	} catch (_) {
		if (window.spkmodServerHealth) window.spkmodServerHealth.recordFailure();
	} finally {
		lunBotSyncInFlight = false;
	}
}

async function reportBotsToServer(newBotNames = [], removeNames = [], allowPromoteCheck = true) {
	const auth = getBotReporterAuth();
	if (!auth.authorized) {
		fetchRemoteBotList();
		return;
	}
	if (window.spkmodServerHealth && !window.spkmodServerHealth.isAvailable()) return;
	if (lunBotSyncInFlight) {
		enqueuePendingBotReport(newBotNames, removeNames, allowPromoteCheck);
		return;
	}

	lunBotSyncInFlight = true;
	try {
		const safeFetch = window.spkmodSafeFetch || window.fetch;
		const res = await safeFetch(`${SPKMOD_SERVER_URL}/api/bots/report`, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({
				username: auth.username,
				playerId: auth.playerId,
				level: auth.level,
				bots: newBotNames,
				removeNames
			})
		}, 5000);
		if (!res.ok) throw new Error(`HTTP ${res.status}`);
		const data = await res.json();
		if (window.spkmodServerHealth) window.spkmodServerHealth.recordSuccess();
		if (data && data.success) {
			if (Array.isArray(newBotNames)) {
				for (const item of newBotNames) {
					const rawName = (item && typeof item === "object") ? item.name : item;
					if (typeof rawName === "string") {
						lunLocalPendingBots.delete(rawName.trim().toLocaleLowerCase());
					}
				}
			}
			if (Array.isArray(data.bots)) {
				applyServerBotList(data.bots, allowPromoteCheck);
			}
		}
	} catch (_) {
		if (window.spkmodServerHealth) window.spkmodServerHealth.recordFailure();
	} finally {
		lunBotSyncInFlight = false;
		if (lunPendingBotReportQueue) {
			const queued = lunPendingBotReportQueue;
			lunPendingBotReportQueue = null;
			setTimeout(() => {
				reportBotsToServer(queued.bots, [...queued.removeNames], queued.allowPromoteCheck);
			}, 3100);
		}
	}
}

setTimeout(() => {
	if (typeof fetchRemoteBotList === "function") {
		fetchRemoteBotList();
	}
}, 3000);

function isKnownBotName(name, level, accountId) {
	if (typeof name !== "string") return false;
	const normalizedName = name.trim();
	const lowerName = normalizedName.toLocaleLowerCase();
	
	let isBot = false;
	const parsedLevel = typeof level === "number" ? level : parseInt(level);
	
	if (lunKnownBotNameSet.has(lowerName)) {
		isBot = true;
	} else if (!isNaN(parsedLevel)) {
		if (parsedLevel <= 3 && lunAutoBannedLevel1s.has(lowerName)) {
			isBot = true;
		}
		if (!isBot && parsedLevel <= 2) {
			if (/^[Il]{6,10}[0-9]{2}$/.test(normalizedName)) isBot = true;
			if (/^[O0]{6,10}[0-9]{2}$/.test(normalizedName)) isBot = true;
		}
		if (!isBot && parsedLevel === 1) {
			if (lowerName.includes("spk") || lowerName.includes("스핔이")) isBot = true;
			else if (/^[a-z]+\d+[a-z]+\d+$/i.test(normalizedName)) isBot = true;
			else if (/^\d+[a-z]+\d+$/i.test(normalizedName)) isBot = true;
			else if (/^\d+[a-z]+\d+[a-z]+$/i.test(normalizedName)) isBot = true;
			else if (/^\d{1,2}[a-z]+$/i.test(normalizedName)) isBot = true;
			else if (/^[a-z]+\d{1,2}[a-z]+$/i.test(normalizedName)) isBot = true;
			else if (/^\d+[a-z]+\d+[a-z]+\d+$/i.test(normalizedName)) isBot = true;
		}
	}
	
	const accountIdNum = parseInt(accountId) || 0;
	
	if (isBot) {
		if (accountIdNum > 0) {
			lunActiveBotWaveMinId = Math.min(lunActiveBotWaveMinId, accountIdNum);
		}
		return true;
	}
	
	// Dynamic Strict Net with Prefix Matching
	if (accountIdNum > 0 && accountIdNum >= lunActiveBotWaveMinId && parsedLevel === 1) {
		const letters = lowerName.replace(/[^a-z]/g, '');
		let isLooseMatch = false;
		for (const prefix of lunKnownBotPrefixSet) {
			if (letters.startsWith(prefix)) {
				isLooseMatch = true;
				break;
			}
		}
		if (isLooseMatch) {
			return true;
		}
	}
	
	return false;
}

var lunSpkAuthToken = "";
var cachedBlockedNames = new Set();
var cachedBlockIds = new Map();

let legacyBlockedNamesCache = null;
let spkmodBlockNameCounts = new Map();
let spkmodBlockOrphanNames = new Set();
let spkmodBlocklistSnapshotSignature = null;
let spkmodBlocklistInFlight = null;
let spkmodBlocklistInFlightToken = "";
let spkmodBlocklistRequestVersion = 0;
let spkmodBlocklistFetchTimer = null;

function getLegacyBlockedNamesCache() {
    if (legacyBlockedNamesCache instanceof Set) {
        return legacyBlockedNamesCache;
    }

    const names = new Set();

    try {
        const stored = JSON.parse(localStorage.getItem("sr1_blocked_players") || "[]");

        if (Array.isArray(stored)) {
            for (const name of stored) {
                if (typeof name !== "string") continue;

                const clean = name.trim().toLocaleLowerCase();

                if (clean) names.add(clean);
            }
        }
    } catch (_) {}

    legacyBlockedNamesCache = names;

    return legacyBlockedNamesCache;
}

function normalizeBlockedNickname(name) {
    if (typeof name !== "string") return "";

    return name.trim().toLocaleLowerCase();
}

function spkmodAdjustBlockedNameCount(name, delta) {
    const next = (spkmodBlockNameCounts.get(name) || 0) + delta;

    if (next <= 0) {
        spkmodBlockNameCounts.delete(name);
        cachedBlockedNames.delete(name);
    } else {
        spkmodBlockNameCounts.set(name, next);
        cachedBlockedNames.add(name);
    }
}

function spkmodApplyBlocklistSnapshot(blocks) {
    const nextIds = new Map();
    const nextOrphans = new Set();

    for (const block of blocks) {
        const nickname = normalizeBlockedNickname(block?.nickname);

        if (!nickname) continue;

        if (block.blockId == null) {
            nextOrphans.add(nickname);
        } else {
            nextIds.set(String(block.blockId), nickname);
        }
    }

    const nextCounts = new Map();

    for (const nickname of nextIds.values()) {
        nextCounts.set(nickname, (nextCounts.get(nickname) || 0) + 1);
    }

    for (const nickname of nextOrphans) {
        nextCounts.set(nickname, (nextCounts.get(nickname) || 0) + 1);
    }

    const signature = JSON.stringify({
        ids: [...nextIds.entries()].sort((a, b) => a[0].localeCompare(b[0])),
        orphans: [...nextOrphans].sort()
    });

    if (signature === spkmodBlocklistSnapshotSignature) {
        return false;
    }

    cachedBlockIds.clear();
    cachedBlockedNames.clear();

    for (const [id, nickname] of nextIds) {
        cachedBlockIds.set(id, nickname);
    }

    for (const nickname of nextCounts.keys()) {
        cachedBlockedNames.add(nickname);
    }

    spkmodBlockNameCounts = nextCounts;
    spkmodBlockOrphanNames = nextOrphans;
    spkmodBlocklistSnapshotSignature = signature;

    updateKnownBotVisibility();

    return true;
}

function spkmodApplyBlocklistEntry(entry) {
    const nickname = normalizeBlockedNickname(entry?.nickname);

    if (!nickname) return false;

    if (entry.blockId == null) {
        if (spkmodBlockOrphanNames.has(nickname)) return false;

        spkmodBlockOrphanNames.add(nickname);
        spkmodAdjustBlockedNameCount(nickname, 1);
    } else {
        const id = String(entry.blockId);
        const oldName = cachedBlockIds.get(id);

        if (oldName === nickname) return false;

        if (oldName) {
            spkmodAdjustBlockedNameCount(oldName, -1);
        }

        cachedBlockIds.set(id, nickname);
        spkmodAdjustBlockedNameCount(nickname, 1);
    }

    spkmodBlocklistSnapshotSignature = null;
    updateKnownBotVisibility();

    return true;
}

function spkmodApplyBlocklistPayload(data) {
    if (Array.isArray(data?.blocks)) {
        return spkmodApplyBlocklistSnapshot(data.blocks);
    }

    if (typeof data?.nickname === "string") {
        return spkmodApplyBlocklistEntry(data);
    }

    return false;
}

function spkmodDeleteBlocklistEntry(blockId) {
    const id = String(blockId);
    const nickname = cachedBlockIds.get(id);

    if (!nickname) {
        scheduleSpkmodBlocklistFetch();
        return;
    }

    cachedBlockIds.delete(id);
    spkmodAdjustBlockedNameCount(nickname, -1);

    spkmodBlocklistSnapshotSignature = null;
    updateKnownBotVisibility();
}

function scheduleSpkmodBlocklistFetch(delay = 100) {
    if (spkmodBlocklistFetchTimer !== null) return;

    spkmodBlocklistFetchTimer = setTimeout(() => {
        spkmodBlocklistFetchTimer = null;
        spkmodFetchBlocklist();
    }, delay);
}

async function spkmodFetchBlocklist() {
    const token = lunSpkAuthToken;

    if (!token) {
        scheduleSpkmodBlocklistFetch(1000);
        return;
    }

    if (spkmodBlocklistInFlight && spkmodBlocklistInFlightToken === token) {
        return spkmodBlocklistInFlight;
    }

    const version = ++spkmodBlocklistRequestVersion;

    const request = (async () => {
        try {
            const apiUrl = (typeof window.lunActiveApiEndpoint !== "undefined" ? window.lunActiveApiEndpoint : "https://sr1.overture.io.kr") + "/api/block";

            const res = await lunBlocklistFetchOrig.call(window, apiUrl, {
                method: "GET",
                cache: "no-store",
                headers: {
                    Authorization: token
                }
            });

            if (!res.ok) return;

            const data = await res.json();

            if (version !== spkmodBlocklistRequestVersion || token !== lunSpkAuthToken) {
                return;
            }

            spkmodApplyBlocklistPayload(data);
        } catch (e) {
            console.warn("[SpeakiMod+] Failed to fetch native blocklist:", e);
        }
    })();

    spkmodBlocklistInFlight = request;
    spkmodBlocklistInFlightToken = token;

    try {
        return await request;
    } finally {
        if (spkmodBlocklistInFlight === request) {
            spkmodBlocklistInFlight = null;
            spkmodBlocklistInFlightToken = "";
        }
    }
}

// Run it once on load
// Intercept window.fetch
const lunBlocklistFetchOrig = window.fetch;

window.fetch = async function(...args) {
    try {
        let auth = "";
        if (args[1] && args[1].headers && args[1].headers.Authorization) auth = args[1].headers.Authorization;
        else if (args[1] && args[1].headers && typeof args[1].headers.get === 'function') auth = args[1].headers.get('Authorization') || "";
        else if (args[0] && args[0].headers && typeof args[0].headers.get === 'function') auth = args[0].headers.get('Authorization') || "";
		
		if (auth && auth.startsWith("Bearer ") && lunSpkAuthToken !== auth) {
			lunSpkAuthToken = auth;
			spkmodBlocklistRequestVersion++;
			scheduleSpkmodBlocklistFetch(100);
		}
    } catch(e) {}

    const response = await lunBlocklistFetchOrig.apply(this, args);

    try {
		if (response.ok) {
			const url = typeof args[0] === 'string' ? args[0] : (args[0]?.url || '');
			let method = 'GET';
			if (args[1] && args[1].method) method = args[1].method;
			else if (args[0] && args[0].method) method = args[0].method;
			method = method.toUpperCase();
			const blockDeleteMatch = url.match(/\/api\/block\/([^/?#]+)\/?(?:[?#]|$)/);
			const friendDeleteMatch = url.match(/\/api\/friend\/([^/?#]+)\/?$/);
			
			if (method === "DELETE" && blockDeleteMatch) {
				const blockId = decodeURIComponent(blockDeleteMatch[1]);
				spkmodDeleteBlocklistEntry(blockId);
			}
			else if (url.includes("/api/block") && !blockDeleteMatch) {
				response.clone().json().then(spkmodApplyBlocklistPayload).catch(() => {});
			}
		    else if (url.includes('/api/friend/list')) {
			    try {
				    const data = await response.clone().json();
				    replaceFriendNicknames(data);
			    } catch (_) {}
		    }
		    else if (method === "DELETE" && friendDeleteMatch) {
			    const friendshipId = decodeURIComponent(friendDeleteMatch[1]);
			    const deletedNickname = lunFriendshipNicknamesById.get(friendshipId);
			    if (deletedNickname) {
				    lunFriendNicknames.delete(deletedNickname);
				    lunFriendshipNicknamesById.delete(friendshipId);
				    try {
					    localStorage.setItem("spkmod-friend-cache", JSON.stringify([...lunFriendNicknames]));
				    } catch (_) {}
				    if (lunNametagMode === 2) refreshAllNametags();
			    }
		    }
	    }
    } catch (e) {}

    return response;
};

// Intercept XMLHttpRequest
const origOpen = XMLHttpRequest.prototype.open;
XMLHttpRequest.prototype.open = function(method, url) {
    this._spkUrl = url;
	this._spkMethod = String(method || 'GET').toUpperCase();
    return origOpen.apply(this, arguments);
};
const origSetReqHeader = XMLHttpRequest.prototype.setRequestHeader;
XMLHttpRequest.prototype.setRequestHeader = function(header, value) {
    if (header.toLowerCase() === "authorization" && value && value.startsWith("Bearer ") && lunSpkAuthToken !== value) {
		lunSpkAuthToken = value;
        spkmodBlocklistRequestVersion++;
        scheduleSpkmodBlocklistFetch(100);
    }
    return origSetReqHeader.apply(this, arguments);
};
const origSend = XMLHttpRequest.prototype.send;
XMLHttpRequest.prototype.send = function() {
    this.addEventListener('load', function() {
        if (this.status >= 200 && this.status < 300 && this._spkUrl && typeof this._spkUrl === 'string' && this._spkUrl.includes('/api/block')) {
			try {
				const blockDeleteMatch = this._spkUrl.match(/\/api\/block\/([^/?#]+)\/?(?:[?#]|$)/);
				if (this._spkMethod === "DELETE" && blockDeleteMatch) {
					const blockId = decodeURIComponent(blockDeleteMatch[1]);
					spkmodDeleteBlocklistEntry(blockId);
				}
				else if (!blockDeleteMatch) {
					const data = JSON.parse(this.responseText);
					spkmodApplyBlocklistPayload(data);
				}
            } catch (_) {}
        }
    });
    return origSend.apply(this, arguments);
};

function isBlockedUser(name) {
    if (typeof name !== "string") return false;

    const clean = name.trim().toLocaleLowerCase();

    if (!clean) return false;

    return cachedBlockedNames.has(clean) || getLegacyBlockedNamesCache().has(clean);
}

window.addEventListener("storage", e => {
    if (e.key !== "sr1_blocked_players") return;

    legacyBlockedNamesCache = null;
    updateKnownBotVisibility();
});

let spkmodVisibilityFlushQueued = false;

function updateKnownBotVisibility() {
    if (spkmodVisibilityFlushQueued) return;

    spkmodVisibilityFlushQueued = true;

    const flush = () => {
        spkmodVisibilityFlushQueued = false;
        spkmodApplyKnownBotVisibility();
    };

    if (typeof queueMicrotask === "function") {
        queueMicrotask(flush);
    } else {
        Promise.resolve().then(flush);
    }
}

function spkmodApplyKnownBotVisibility() {
    const remoteMap = gameState?.remotePlayers?.remotePlayers;

    if (!(remoteMap instanceof Map)) return;

    for (const player of remoteMap.values()) {
        const container = player?.container;

        if (!container) continue;

        const name = player.info?.name;
        const accId = player.info?.userId || player.info?.id || player.info?.playerId;

        const isBot = lunHideKnownBotsEnabled && isKnownBotName(name, player.info?.level, accId);
        const isBlocked = isBlockedUser(name);
        const isWhitelisted = isSolitudeWhitelisted(name);
        const hideBySolitude = lunHideAllOtherPlayers && !isWhitelisted;
        const visible = !(hideBySolitude || isBot || isBlocked);

        if (container.visible !== visible) {
            container.visible = visible;
        }
    }

    const applyCompanionVisibility = companionMap => {
        if (!(companionMap instanceof Map)) return;

        for (const [ownerId, companion] of companionMap) {
            const owner = remoteMap.get(ownerId) ?? remoteMap.get(Number(ownerId));
            const root = companion?.parts?.root;

            if (!root) continue;

            if (!owner?.info) {
                if (root.visible !== false) root.visible = false;
                continue;
            }

            const ownerName = owner.info.name;
            const ownerAccountId = owner.info.userId || owner.info.id || owner.info.playerId;
            const ownerIsBot = lunHideKnownBotsEnabled && isKnownBotName(ownerName, owner.info.level, ownerAccountId);
            const ownerIsBlocked = isBlockedUser(ownerName);
            const ownerIsWhitelisted = isSolitudeWhitelisted(ownerName);
            const hideOwnerBySolitude = lunHideAllOtherPlayers && !ownerIsWhitelisted;
            const visible = !(hideOwnerBySolitude || ownerIsBot || ownerIsBlocked);

            if (root.visible !== visible) {
                root.visible = visible;
            }
        }
    };

    applyCompanionVisibility(gameState.remotePetRegistry?.pets);
    applyCompanionVisibility(gameState.remoteDroneCoreRegistry?.drones);
}

function spkmodHookVisibilityMap(map) {
    if (!(map instanceof Map) || map.__spkmodVisibilityHooked) return;

    map.__spkmodVisibilityHooked = true;

    const originalSet = map.set.bind(map);
    const originalDelete = map.delete.bind(map);
    const originalClear = map.clear.bind(map);

    map.set = function(key, value) {
        const result = originalSet(key, value);
        updateKnownBotVisibility();
        return result;
    };

    map.delete = function(key) {
        const result = originalDelete(key);

        if (result) updateKnownBotVisibility();

        return result;
    };

    map.clear = function() {
        const hadItems = this.size > 0;
        const result = originalClear();

        if (hadItems) updateKnownBotVisibility();

        return result;
    };
}

function isKnownBotContainer(container) {
	if (!container || !gameState?.remotePlayers?.remotePlayers) return false;
	
	let current = container;
	while (current) {
		for (const player of gameState.remotePlayers.remotePlayers.values()) {
			if (player?.container === current) return isKnownBotName(player.info?.name, player.info?.level);
		}
		current = current.parent;
	}
	return false;
}

function isBlockedUserContainer(container) {
	if (!container || !gameState?.remotePlayers?.remotePlayers) return false;
	
	let current = container;
	while (current) {
		for (const player of gameState.remotePlayers.remotePlayers.values()) {
			if (player?.container === current) return isBlockedUser(player.info?.name);
		}
		current = current.parent;
	}
	return false;
}

function isKnownBotBubbleSource(source) {
	if (!source || !gameState?.remotePlayers?.remotePlayers) return false;
	if (isKnownBotContainer(source) || isKnownBotContainer(source.container)) return true;
	if (isKnownBotName(source.info?.name, source.info?.level, source.info?.userId || source.info?.id || source.info?.playerId)) return true;
	if (isKnownBotName(source.name, source.level, source.userId || source.id || source.playerId)) return true;

	for (const player of gameState.remotePlayers.remotePlayers.values()) {
		const playerInfo = player?.info;
		if (playerInfo && (source === playerInfo.playerId || source === playerInfo.id || source === playerInfo.userId)) {
			return isKnownBotName(playerInfo.name, playerInfo.level, playerInfo.userId || playerInfo.id || playerInfo.playerId);
		}
	}
	return false;
}

function isBlockedUserBubbleSource(source) {
	if (!source || !gameState?.remotePlayers?.remotePlayers) return false;
	if (isBlockedUserContainer(source) || isBlockedUserContainer(source.container)) return true;
	if (isBlockedUser(source.info?.name)) return true;
	if (isBlockedUser(source.name)) return true;

	for (const player of gameState.remotePlayers.remotePlayers.values()) {
		const playerInfo = player?.info;
		if (playerInfo && (source === playerInfo.playerId || source === playerInfo.id || source === playerInfo.userId)) {
			return isBlockedUser(playerInfo.name);
		}
	}
	return false;
}

function isSolitudeWhitelistedContainer(container) {
	if (!container || !gameState?.remotePlayers?.remotePlayers || typeof isSolitudeWhitelisted !== "function") return false;
	let current = container;
	while (current) {
		for (const player of gameState.remotePlayers.remotePlayers.values()) {
			if (player?.container === current) return isSolitudeWhitelisted(player.info?.name);
		}
		current = current.parent;
	}
	return false;
}

function isSolitudeWhitelistedBubbleSource(source) {
	if (!source || !gameState?.remotePlayers?.remotePlayers || typeof isSolitudeWhitelisted !== "function") return false;
	if (isSolitudeWhitelistedContainer(source) || isSolitudeWhitelistedContainer(source.container)) return true;
	if (isSolitudeWhitelisted(source.info?.name)) return true;
	if (isSolitudeWhitelisted(source.name)) return true;

	for (const player of gameState.remotePlayers.remotePlayers.values()) {
		const playerInfo = player?.info;
		if (playerInfo && (source === playerInfo.playerId || source === playerInfo.id || source === playerInfo.userId)) {
			return isSolitudeWhitelisted(playerInfo.name);
		}
	}
	return false;
}

function hookKnownBotHeartEmotes() {
	const bloomEffects = gameState?.bloomEffects;
	if (!bloomEffects || typeof bloomEffects.spawnHearts !== "function" || bloomEffects.__speakiKnownBotHooked) return;

	const originalSpawnHearts = bloomEffects.spawnHearts.bind(bloomEffects);
	bloomEffects.spawnHearts = function(container, ...args) {
		if (lunHideAllOtherPlayers && !isSolitudeWhitelistedContainer(container)) return;
		if (lunHideKnownBotsEnabled && isKnownBotContainer(container)) return;
		if (isBlockedUserContainer(container)) return;
		return originalSpawnHearts(container, ...args);
	};
	bloomEffects.__speakiKnownBotHooked = true;
}

function containsRemoteEmote(value, seen = new Set()) {
	if (typeof value === "number") return Number.isInteger(value) && value >= 1 && value <= 8;
	if (!value || typeof value !== "object" || seen.has(value)) return false;
	seen.add(value);

	for (const key of ["emote", "emoteId", "emoteID", "emoteType", "action", "actionId", "id", "val", "value", "data"]) {
		if (value[key] !== undefined && containsRemoteEmote(value[key], seen)) return true;
	}
	return false;
}

function hookKnownBotPlayerEmotes(player) {
	if (!player || player.__speakiKnownBotEmotesHooked) return;
	const methodNames = new Set();
	let current = player;
	while (current && current !== Object.prototype) {
		Object.getOwnPropertyNames(current).forEach(name => methodNames.add(name));
		current = Object.getPrototypeOf(current);
	}

	for (const name of methodNames) {
		if (name === "constructor" || !/emote|emotion|action|animation|effect|update|handle|receive|message/i.test(name)) continue;
		const original = player[name];
		if (typeof original !== "function") continue;
		try {
			player[name] = function(...args) {
				if (lunHideKnownBotsEnabled && isKnownBotName(this.info?.name, this.info?.level) && args.some(arg => containsRemoteEmote(arg))) {
					return;
				}
				return original.apply(this, args);
			};
		} catch (err) {}
	}
	player.__speakiKnownBotEmotesHooked = true;
}

function hookKnownBotPlayerEmotesForAll() {
	if (!gameState?.remotePlayers?.remotePlayers) return;
	gameState.remotePlayers.remotePlayers.forEach(hookKnownBotPlayerEmotes);
}

function resolveRemotePlayerById(playerId) {
    if (!gameState?.remotePlayers) return null;
    const rp = gameState.remotePlayers;
    let p = rp.get?.(playerId) || rp.get?.(Number(playerId)) || rp.get?.(String(playerId));
    if (p) return p;
    if (rp.remotePlayers instanceof Map) {
        p = rp.remotePlayers.get(playerId) || rp.remotePlayers.get(Number(playerId)) || rp.remotePlayers.get(String(playerId));
        if (p) return p;
        for (const item of rp.remotePlayers.values()) {
            if (item?.info?.playerId == playerId) return item;
        }
    } else if (typeof rp.values === "function") {
        for (const item of rp.values()) {
            if (item?.info?.playerId == playerId) return item;
        }
    }
    return null;
}

function isSilencedPlayer(player) {
    if (!player) return false;
    const name = player.info?.name || player.name;
    const isWhitelisted = typeof isSolitudeWhitelisted === "function" && isSolitudeWhitelisted(name);
    if (lunHideAllOtherPlayers && !isWhitelisted) return true;
    if (!name || typeof name !== "string") return false;
    const lower = name.trim().toLocaleLowerCase();
    if (!lower) return false;
    if (isBlockedUser(name)) return true;
    const accId = player.info?.userId || player.info?.id || player.info?.playerId;
    const level = player.info?.level || player.level;
    if (typeof isKnownBotName === "function" && isKnownBotName(name, level, accId)) return true;
    return false;
}

function hookBlockedUserVoice() {
    if (typeof gameState === "undefined" || !gameState) return;

    if (!gameState.__spkmodHandleEmoteHooked && typeof gameState.handleEmote === "function") {
        const originalHandleEmote = gameState.handleEmote;

        gameState.handleEmote = function(e) {
            if (!e || e.playerId === this.myPlayerId) {
                return originalHandleEmote.call(this, e);
            }

            let remotePlayer = resolveRemotePlayerById(e.playerId);

            if (!remotePlayer && gameState?.remotePlayers) {
                const list = gameState.remotePlayers.remotePlayers instanceof Map
                    ? gameState.remotePlayers.remotePlayers.values()
                    : (typeof gameState.remotePlayers.values === "function" ? gameState.remotePlayers.values() : []);

                for (const p of list) {
                    if (p?.info?.playerId == e.playerId) {
                        remotePlayer = p;
                        break;
                    }
                }
            }

            if (isSilencedPlayer(remotePlayer)) return;

            return originalHandleEmote.call(this, e);
        };

        gameState.__spkmodHandleEmoteHooked = true;
    }

    if (!gameState.__spkmodRemoteSoundDistanceHooked && typeof gameState.remoteSoundDistance === "function") {
        const originalSoundDist = gameState.remoteSoundDistance;

        gameState.remoteSoundDistance = function(pos) {
            if (pos && gameState.remotePlayers) {
                const list = gameState.remotePlayers.remotePlayers instanceof Map
                    ? gameState.remotePlayers.remotePlayers.values()
                    : (typeof gameState.remotePlayers.values === "function" ? gameState.remotePlayers.values() : []);

                for (const p of list) {
                    const cPos = p?.container?.position;

                    if (!cPos) continue;

                    const dx = cPos.x - pos.x;
                    const dz = cPos.z - pos.z;

                    if (!Number.isFinite(dx) || !Number.isFinite(dz) || dx * dx + dz * dz >= 0.01) {
                        continue;
                    }

                    if (isSilencedPlayer(p)) {
                        return 999999;
                    }
                }
            }

            return originalSoundDist.apply(this, arguments);
        };

        gameState.__spkmodRemoteSoundDistanceHooked = true;
    }

    gameState.__speakiBlockedUserVoiceHooked = !!gameState.__spkmodHandleEmoteHooked && !!gameState.__spkmodRemoteSoundDistanceHooked;
}

