				const now = Date.now();
				if (now - (window.__spkmodGlasLastClick || 0) > 3000) window.__spkmodGlasClicks = 0;
				window.__spkmodGlasLastClick = now;
				window.__spkmodGlasClicks = (window.__spkmodGlasClicks || 0) + 1;
