window.spkmodActiveFloatingButtons = new Map(); // sourceElement -> floatingElement

function spkmodGetButtonId(btn) {
    if (!btn) return null;
    if (btn.dataset && btn.dataset.spkmodBtnId) return btn.dataset.spkmodBtnId;
    if (btn.id) {
        btn.dataset.spkmodBtnId = "id:" + btn.id;
        return btn.dataset.spkmodBtnId;
    }

    if (typeof lunPanelElements === "object" && lunPanelElements) {
        for (const [key, el] of Object.entries(lunPanelElements)) {
            if (el === btn) {
                btn.dataset.spkmodBtnId = "panel:" + key;
                return btn.dataset.spkmodBtnId;
            }
        }
    }
    if (typeof editsModalElements === "object" && editsModalElements) {
        for (const [key, el] of Object.entries(editsModalElements)) {
            if (el === btn) {
                btn.dataset.spkmodBtnId = "edits:" + key;
                return btn.dataset.spkmodBtnId;
            }
        }
    }
    if (typeof lunHudElements === "object" && lunHudElements) {
        for (const [key, el] of Object.entries(lunHudElements)) {
            if (el === btn) {
                btn.dataset.spkmodBtnId = "hud:" + key;
                return btn.dataset.spkmodBtnId;
            }
        }
    }

    const parent = btn.closest("[id]");
    const parentId = parent ? parent.id : "body";
    const title = btn.title || "";
    const text = (btn.innerText || btn.textContent || "").trim();

    const domId = `dom:${parentId}|${title}|${text}`;
    if (btn.dataset) btn.dataset.spkmodBtnId = domId;
    return domId;
}

function spkmodFindButtonById(id) {
    if (!id) return null;

    if (id.startsWith("id:")) {
        return document.getElementById(id.slice(3));
    }
    if (id.startsWith("panel:")) {
        const key = id.slice(6);
        return (typeof lunPanelElements === "object" && lunPanelElements && lunPanelElements[key]) || null;
    }
    if (id.startsWith("edits:")) {
        const key = id.slice(6);
        return (typeof editsModalElements === "object" && editsModalElements && editsModalElements[key]) || null;
    }
    if (id.startsWith("hud:")) {
        const key = id.slice(4);
        return (typeof lunHudElements === "object" && lunHudElements && lunHudElements[key]) || null;
    }
    if (id.startsWith("dom:")) {
        const parts = id.slice(4).split("|");
        const parentId = parts[0];
        const title = parts[1];
        const text = parts[2];
        const root = (parentId && parentId !== "body") ? document.getElementById(parentId) : document.body;
        if (!root) return null;
        const allBtns = root.querySelectorAll("button, .spkmod-panel-btn, .spkmod-quick-btn");
        for (const b of allBtns) {
            if (title && b.title === title) return b;
            if (text && (b.innerText || b.textContent || "").trim() === text) return b;
        }
        return null;
    }
    return null;
}

function spkmodSaveFloatingButtons() {
    try {
        const list = [];
        for (const [sourceBtn, floatingBtn] of window.spkmodActiveFloatingButtons.entries()) {
            if (!floatingBtn || !floatingBtn.parentNode) continue;
            const btnId = spkmodGetButtonId(sourceBtn);
            if (!btnId) continue;
            const left = parseInt(floatingBtn.style.left, 10) || floatingBtn.offsetLeft;
            const top = parseInt(floatingBtn.style.top, 10) || floatingBtn.offsetTop;
            list.push({
                btnId,
                left,
                top
            });
        }
        localStorage.setItem("spkmod-floating-buttons", JSON.stringify(list));
    } catch (e) {
        console.warn("[SpeakiMod+] Failed to save floating buttons to localStorage:", e);
    }
}

function spkmodRestoreFloatingButtons() {
    try {
        const raw = localStorage.getItem("spkmod-floating-buttons");
        if (!raw) return;
        const list = JSON.parse(raw);
        if (!Array.isArray(list)) return;

        for (const item of list) {
            if (!item || !item.btnId) continue;
            const sourceBtn = spkmodFindButtonById(item.btnId);
            if (sourceBtn) {
                if (!window.spkmodActiveFloatingButtons.has(sourceBtn)) {
                    const left = Math.max(10, Math.min(window.innerWidth - 120, item.left));
                    const top = Math.max(10, Math.min(window.innerHeight - 40, item.top));
                    spkmodSpawnFloatingButton(sourceBtn, left, top, true);
                }
            }
        }
    } catch (e) {
        console.warn("[SpeakiMod+] Failed to restore floating buttons from localStorage:", e);
    }
}

function spkmodSpawnFloatingButton(sourceBtn, initialX, initialY, isRestoring = false) {
    if (!sourceBtn) return null;

    // Toggle: If a floating copy already exists for this button, remove it
    if (window.spkmodActiveFloatingButtons.has(sourceBtn)) {
        const existing = window.spkmodActiveFloatingButtons.get(sourceBtn);
        spkmodRemoveFloatingButton(existing);
        return null;
    }

    // Determine initial coordinates
    let spawnLeft = initialX || (window.innerWidth / 2 - 50);
    let spawnTop = initialY || (window.innerHeight / 2 - 20);

    if (initialX !== undefined && initialY !== undefined) {
        spawnLeft = Math.max(10, Math.min(window.innerWidth - 150, initialX + 12));
        spawnTop = Math.max(10, Math.min(window.innerHeight - 50, initialY + 8));
    }

    const floatingBtn = document.createElement("div");
    floatingBtn.className = "spkmod-floating-button";
    floatingBtn.dataset.spkmodFloating = "true";

    const baseColor = sourceBtn.style.color || "#ffd54a";

    floatingBtn.style.cssText = `
        position: fixed;
        left: ${spawnLeft}px;
        top: ${spawnTop}px;
        z-index: 2147483645;
        background: rgba(18, 22, 28, 0.92);
        backdrop-filter: blur(8px);
        -webkit-backdrop-filter: blur(8px);
        border: 1px solid ${sourceBtn.style.borderColor || "rgba(255, 213, 74, 0.65)"};
        border-radius: 6px;
        padding: 6px 12px;
        font-family: inherit;
        font-size: 11px;
        font-weight: bold;
        color: ${baseColor};
        box-shadow: 0 4px 16px rgba(0, 0, 0, 0.65), 0 0 10px rgba(255, 213, 74, 0.25);
        cursor: grab;
        user-select: none;
        touch-action: none;
        display: inline-flex;
        align-items: center;
        gap: 6px;
        transition: transform 0.1s ease, box-shadow 0.15s ease, border-color 0.15s ease;
        max-width: 250px;
        white-space: nowrap;
    `;

    const rawTitle = sourceBtn.title || "";
    floatingBtn.title = (rawTitle ? rawTitle + "\n" : "") + "📌 Left-click: Use | Drag: Move | Right-click: Dismiss";

    // Text Label Container
    const labelSpan = document.createElement("span");
    const rawLabelText = (sourceBtn.innerText || sourceBtn.textContent || "").trim();
    if (rawLabelText) {
        labelSpan.innerText = rawLabelText;
    } else if (sourceBtn.innerHTML) {
        labelSpan.innerHTML = sourceBtn.innerHTML;
    } else {
        labelSpan.innerText = "Action";
    }
    floatingBtn.appendChild(labelSpan);

    // Subtle drag/pin badge
    const pinBadge = document.createElement("span");
    pinBadge.innerText = "📌";
    pinBadge.style.cssText = "font-size: 9px; opacity: 0.65; cursor: grab;";
    floatingBtn.appendChild(pinBadge);

    // Dynamic state synchronizer: keep label and style updated in real-time
    const observer = new MutationObserver(() => {
        if (sourceBtn) {
            const updatedText = (sourceBtn.innerText || sourceBtn.textContent || "").trim();
            if (updatedText) {
                labelSpan.innerText = updatedText;
            } else if (sourceBtn.innerHTML) {
                labelSpan.innerHTML = sourceBtn.innerHTML;
            }
            if (sourceBtn.style.color) {
                floatingBtn.style.color = sourceBtn.style.color;
            }
            if (sourceBtn.style.borderColor) {
                floatingBtn.style.borderColor = sourceBtn.style.borderColor;
            }
        }
    });
    observer.observe(sourceBtn, { childList: true, characterData: true, subtree: true, attributes: true, attributeFilter: ['style', 'class'] });

    floatingBtn.__spkmodSourceBtn = sourceBtn;
    floatingBtn.__spkmodObserver = observer;
    window.spkmodActiveFloatingButtons.set(sourceBtn, floatingBtn);

    // Hover effect
    floatingBtn.onmouseenter = () => {
        if (document.pointerLockElement) {
            try { document.exitPointerLock(); } catch (_) {}
        }
        floatingBtn.style.boxShadow = "0 6px 20px rgba(0, 0, 0, 0.8), 0 0 14px rgba(255, 213, 74, 0.5)";
        floatingBtn.style.borderColor = "#ffd54a";
    };
    floatingBtn.onmouseleave = () => {
        floatingBtn.style.boxShadow = "0 4px 16px rgba(0, 0, 0, 0.65), 0 0 10px rgba(255, 213, 74, 0.25)";
        floatingBtn.style.borderColor = sourceBtn.style.borderColor || "rgba(255, 213, 74, 0.65)";
    };

    // Right-click: clean & dismiss
    floatingBtn.oncontextmenu = (e) => {
        e.preventDefault();
        e.stopPropagation();
        spkmodRemoveFloatingButton(floatingBtn);
    };

    // Drag vs Click handlers
    let isDragging = false;
    let startX = 0, startY = 0;
    let elemLeft = 0, elemTop = 0;

    function onPointerMove(e) {
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        if (!isDragging && Math.hypot(dx, dy) > 4) {
            isDragging = true;
            floatingBtn.style.cursor = "grabbing";
        }
        if (isDragging) {
            const newLeft = Math.max(0, Math.min(window.innerWidth - floatingBtn.offsetWidth, elemLeft + dx));
            const newTop = Math.max(0, Math.min(window.innerHeight - floatingBtn.offsetHeight, elemTop + dy));
            floatingBtn.style.left = newLeft + "px";
            floatingBtn.style.top = newTop + "px";
        }
    }

    function onPointerUp(e) {
        window.removeEventListener("pointermove", onPointerMove);
        window.removeEventListener("pointerup", onPointerUp);
        floatingBtn.style.cursor = "grab";

        if (isDragging) {
            spkmodSaveFloatingButtons();
        }

        if (!isDragging && e.button === 0) {
            if (spkmodTouchPinTriggered || floatingBtn.__spkmodDismissed || !floatingBtn.parentNode) {
                return;
            }
            // Click animation
            floatingBtn.style.transform = "scale(0.92)";
            setTimeout(() => {
                if (floatingBtn && floatingBtn.parentNode) floatingBtn.style.transform = "scale(1)";
            }, 120);

            // Execute action
            if (typeof sourceBtn.onclick === "function") {
                sourceBtn.onclick(e);
            } else {
                sourceBtn.click();
            }
        }
    }

    floatingBtn.onpointerdown = (e) => {
        if (e.button !== 0) return; // Only primary mouse button
        if (document.pointerLockElement) {
            try { document.exitPointerLock(); } catch (_) {}
        }
        isDragging = false;
        startX = e.clientX;
        startY = e.clientY;
        elemLeft = floatingBtn.offsetLeft;
        elemTop = floatingBtn.offsetTop;
        window.addEventListener("pointermove", onPointerMove);
        window.addEventListener("pointerup", onPointerUp);
    };

    // Entrance animation
    floatingBtn.style.transform = "scale(0.75)";
    floatingBtn.style.opacity = "0";
    document.body.appendChild(floatingBtn);

    requestAnimationFrame(() => {
        floatingBtn.style.transition = "transform 0.18s cubic-bezier(0.175, 0.885, 0.32, 1.275), opacity 0.18s ease";
        floatingBtn.style.transform = "scale(1)";
        floatingBtn.style.opacity = "1";
    });

    const btnName = (sourceBtn.innerText || sourceBtn.textContent || "Button").trim();
    if (!isRestoring && typeof chatLog === 'function') {
        chatLog(t("floatingBtnPinned", btnName) || `📌 Pinned "${btnName}" outside HUD! (Drag to move, Right-click to dismiss)`);
    }

    spkmodSaveFloatingButtons();
    return floatingBtn;
}

function spkmodRemoveFloatingButton(floatingBtn) {
    if (!floatingBtn) return;
    floatingBtn.__spkmodDismissed = true;
    if (floatingBtn.__spkmodObserver) {
        floatingBtn.__spkmodObserver.disconnect();
        floatingBtn.__spkmodObserver = null;
    }
    if (floatingBtn.__spkmodSourceBtn) {
        window.spkmodActiveFloatingButtons.delete(floatingBtn.__spkmodSourceBtn);
    }

    floatingBtn.style.transition = "transform 0.15s ease, opacity 0.15s ease";
    floatingBtn.style.transform = "scale(0.7)";
    floatingBtn.style.opacity = "0";

    const btnName = floatingBtn.innerText ? floatingBtn.innerText.replace("📌", "").trim() : "Button";

    setTimeout(() => {
        if (floatingBtn.parentNode) {
            floatingBtn.parentNode.removeChild(floatingBtn);
        }
    }, 160);

    spkmodSaveFloatingButtons();

    if (typeof chatLog === 'function') {
        chatLog(t("floatingBtnDismissed", btnName) || `🧹 Floating button "${btnName}" dismissed.`);
    }
}

window.spkmodSpawnFloatingButton = spkmodSpawnFloatingButton;
window.spkmodRemoveFloatingButton = spkmodRemoveFloatingButton;
window.spkmodSaveFloatingButtons = spkmodSaveFloatingButtons;
window.spkmodRestoreFloatingButtons = spkmodRestoreFloatingButtons;

// Auto-restore saved buttons on page load
setTimeout(spkmodRestoreFloatingButtons, 600);
setTimeout(spkmodRestoreFloatingButtons, 1800);
setTimeout(spkmodRestoreFloatingButtons, 3500);

// Mobile Touch "Hold to Pin" (Long-Press) Detector & Desktop Double Right-Click Delegate
let spkmodTouchHoldTimer = null;
let spkmodTouchHoldTarget = null;
let spkmodTouchStartX = 0;
let spkmodTouchStartY = 0;
let spkmodTouchPinTriggered = false;

function spkmodTriggerTouchPin(btn, clientX, clientY) {
    if (!btn) return;
    if (typeof lunDisableRightClickPinning !== "undefined" && lunDisableRightClickPinning) return;

    spkmodTouchPinTriggered = true;
    if (typeof navigator !== "undefined" && navigator.vibrate) {
        try { navigator.vibrate(40); } catch (_) {}
    }

    if (btn.dataset.spkmodFloating === "true" || btn.classList.contains("spkmod-floating-button")) {
        spkmodRemoveFloatingButton(btn);
    } else {
        spkmodSpawnFloatingButton(btn, clientX, clientY);
    }

    setTimeout(() => {
        spkmodTouchPinTriggered = false;
    }, 450);
}

document.addEventListener("touchstart", (e) => {
    // Dismiss rich tooltip on mobile touch
    const tip = document.getElementById("spkmod-rich-tooltip");
    if (tip) tip.style.display = "none";

    if (!e.touches || e.touches.length !== 1) {
        if (spkmodTouchHoldTimer) {
            clearTimeout(spkmodTouchHoldTimer);
            spkmodTouchHoldTimer = null;
            spkmodTouchHoldTarget = null;
        }
        return;
    }

    const touch = e.touches[0];
    const btn = touch.target && touch.target.closest ? touch.target.closest("button.spkmod-panel-btn, #spkmod-effects-modal button, #spkmod-hud button, #spkmod-panel button, .spkmod-quick-btn, .spkmod-floating-button") : null;
    if (!btn) {
        if (spkmodTouchHoldTimer) {
            clearTimeout(spkmodTouchHoldTimer);
            spkmodTouchHoldTimer = null;
            spkmodTouchHoldTarget = null;
        }
        return;
    }

    // Ignore window close buttons, drag handles, or emoji picker items
    if (btn.innerText === "✕" || btn.id === "spkmod-drag-btn" || btn.id === "spkmod-close-btn" || btn.closest("#spkmod-emoji-picker")) return;

    if (typeof lunDisableRightClickPinning !== "undefined" && lunDisableRightClickPinning) return;

    spkmodTouchHoldTarget = btn;
    spkmodTouchStartX = touch.clientX;
    spkmodTouchStartY = touch.clientY;
    spkmodTouchPinTriggered = false;

    if (spkmodTouchHoldTimer) clearTimeout(spkmodTouchHoldTimer);
    spkmodTouchHoldTimer = setTimeout(() => {
        spkmodTouchHoldTimer = null;
        if (spkmodTouchHoldTarget) {
            spkmodTriggerTouchPin(spkmodTouchHoldTarget, spkmodTouchStartX, spkmodTouchStartY);
            spkmodTouchHoldTarget = null;
        }
    }, 500);
}, { passive: true, capture: true });

document.addEventListener("touchmove", (e) => {
    if (!spkmodTouchHoldTimer || !e.touches || e.touches.length === 0) return;
    const touch = e.touches[0];
    const dist = Math.hypot(touch.clientX - spkmodTouchStartX, touch.clientY - spkmodTouchStartY);
    if (dist > 12) {
        clearTimeout(spkmodTouchHoldTimer);
        spkmodTouchHoldTimer = null;
        spkmodTouchHoldTarget = null;
    }
}, { passive: true, capture: true });

document.addEventListener("touchend", (e) => {
    if (spkmodTouchHoldTimer) {
        clearTimeout(spkmodTouchHoldTimer);
        spkmodTouchHoldTimer = null;
        spkmodTouchHoldTarget = null;
    }
    if (spkmodTouchPinTriggered) {
        e.preventDefault();
        e.stopPropagation();
    }
}, { capture: true });

document.addEventListener("touchcancel", () => {
    if (spkmodTouchHoldTimer) {
        clearTimeout(spkmodTouchHoldTimer);
        spkmodTouchHoldTimer = null;
        spkmodTouchHoldTarget = null;
    }
}, { passive: true, capture: true });

// Prevent accidental clicks on button release after holding to pin
document.addEventListener("click", (e) => {
    if (spkmodTouchPinTriggered) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
    }
}, true);

// Global Double Right-Click Delegate for summoning buttons outside HUD (Desktop) & contextmenu handshake (Mobile)
let spkmodLastRightClickBtn = null;
let spkmodLastRightClickTime = 0;

document.addEventListener("contextmenu", (e) => {
    if (spkmodTouchPinTriggered) {
        e.preventDefault();
        e.stopPropagation();
        return;
    }

    const btn = e.target.closest("button.spkmod-panel-btn, #spkmod-effects-modal button, #spkmod-hud button, #spkmod-panel button, .spkmod-quick-btn, .spkmod-floating-button");
    if (!btn) return;
    
    // Ignore window close buttons, drag handles, or emoji picker items
    if (btn.innerText === "✕" || btn.id === "spkmod-drag-btn" || btn.id === "spkmod-close-btn" || btn.closest("#spkmod-emoji-picker")) return;

    if (typeof lunDisableRightClickPinning !== "undefined" && lunDisableRightClickPinning) {
        return;
    }

    // Handshake: If mobile long-press dispatched a contextmenu while hold timer is active
    if (spkmodTouchHoldTimer && spkmodTouchHoldTarget === btn) {
        e.preventDefault();
        e.stopPropagation();
        clearTimeout(spkmodTouchHoldTimer);
        spkmodTouchHoldTimer = null;
        spkmodTouchHoldTarget = null;
        spkmodTriggerTouchPin(btn, e.clientX, e.clientY);
        return;
    }

    // If right-clicked a floating button itself on desktop, handled by its own listener
    if (btn.dataset.spkmodFloating === "true" || btn.classList.contains("spkmod-floating-button")) return;

    e.preventDefault();
    e.stopPropagation();

    const now = Date.now();
    if (spkmodLastRightClickBtn === btn && (now - spkmodLastRightClickTime) <= 500) {
        spkmodLastRightClickBtn = null;
        spkmodLastRightClickTime = 0;
        spkmodSpawnFloatingButton(btn, e.clientX, e.clientY);
    } else {
        spkmodLastRightClickBtn = btn;
        spkmodLastRightClickTime = now;
    }
}, true);


const lunJumpAnimMs = 500;

const lunFaintAnimMs = 1200;
function autoFaintLoop() {
	if (typeof isFaintBlockedZone === "function" && isFaintBlockedZone()) {
		if (typeof syncFaintButtonsForZone === "function") {
			syncFaintButtonsForZone();
		} else {
			window.AutoFaintActive = false;
			window.__autoFaintPhase = false;
			clearTimeout(window.__autoFaintTimeoutId);
		}
		return;
	}
	if (!window.AutoFaintActive) {
		window.__autoFaintPhase = false;
		return;
	}
	if (typeof gameState !== "undefined" && gameState && typeof gameState.sendEmoteNow === "function") {
		window.__autoFaintPhase = !window.__autoFaintPhase;
		gameState.sendEmoteNow(window.__autoFaintPhase ? (typeof Emotes !== "undefined" ? Emotes.MinigameJoayo || 3 : 3) : 15);
	}
	window.__autoFaintTimeoutId = setTimeout(autoFaintLoop, lunFaintAnimMs);
}

function spkmodPerformJump() {
	if (typeof gameState !== "undefined" && gameState) {
		if (typeof gameState.tryJump === "function") {
			gameState.tryJump();
		} else if (typeof gameState.sendEmoteNow === "function") {
			gameState.sendEmoteNow(Emotes.Jump);
		}
	}
}

function autoJumpLoop() {
	if (!window.AutoJumpActive) return;
	
	let nextDelay = lunJumpAnimMs;
	
	if (typeof gameState !== "undefined" && gameState?.isLocalOnTrampoline && gameState.isLocalOnTrampoline()) {
		const rhythm = gameState.trampolineRhythm;
		const nowSec = performance.now() / 1000;
		if (rhythm) {
			if (!rhythm.airborne) {
				spkmodPerformJump();
				if (rhythm.airborne && rhythm.landAtSec > nowSec) {
					nextDelay = Math.max(30, Math.floor((rhythm.landAtSec - nowSec) * 1000) - 60);
				} else {
					nextDelay = 100;
				}
			} else {
				const timeToLand = (rhythm.landAtSec - nowSec) * 1000;
				if (timeToLand <= 150) {
					spkmodPerformJump();
					nextDelay = 250;
				} else {
					nextDelay = Math.max(30, Math.floor(timeToLand - 60));
				}
			}
		} else {
			spkmodPerformJump();
		}
	} else {
		if (!(typeof window.spkmodHasActiveLocalVehicle === "function" && window.spkmodHasActiveLocalVehicle())) {
			spkmodPerformJump();
		}
	}
	
	window.__autoJumpTimeoutId = setTimeout(autoJumpLoop, nextDelay);
}

const lunHeartsAnimMs = 1100; // Debounce window is 1100ms; 1100ms pushes the limit of no dropped packets on server/clients

function triggerHearts() {
	if (gameState && gameState.bloomEffects && typeof gameState.bloomEffects.spawnHearts === "function") {
		if (gameState.playerContainer) {
			gameState.bloomEffects.spawnHearts(gameState.playerContainer);
		}
		if (lunFollowTargetName && gameState.remotePlayers && gameState.remotePlayers.remotePlayers) {
			const tp = Array.from(gameState.remotePlayers.remotePlayers.values()).find(t => t.info && (t.info.name === lunFollowTargetName || t.info.__spkmodOrigName === lunFollowTargetName));
			if (tp && tp.container && tp.container !== gameState.playerContainer) {
				gameState.bloomEffects.spawnHearts(tp.container);
			}
		}
	}
	if (gameState && typeof gameState.sendEmoteNow === "function") {
		// If Pet Dance is active, don't interrupt the dance emote with StrokeBloom!
		if (!window.PetDanceActive) {
			gameState.sendEmoteNow(Emotes.StrokeBloom);
		}
	}
}

function autoHeartsLoop() {
	if (!window.AutoHeartsActive) return;
	triggerHearts();
	window.__autoHeartsTimeoutId = setTimeout(autoHeartsLoop, lunHeartsAnimMs);
}

window.AutoChowayoActive = false;
window.__autoChowayoTimeoutId = null;
const lunChowayoAnimMs = 2800; // tuned for sync

function autoChowayoLoop() {
	if (!window.AutoChowayoActive) return;
	if (gameState && typeof gameState.sendEmoteNow === "function") {
		gameState.sendEmoteNow(Emotes.MinigameJoayo);
	}
	window.__autoChowayoTimeoutId = setTimeout(autoChowayoLoop, lunChowayoAnimMs);
}

window.AutoMopActive = false;
const lunMopPatchedControllers = new WeakSet();

function spkmodGetLocalAnimController() {
	if (typeof gameState === "undefined" || !gameState) return null;
	return gameState.localAnimationController || gameState.localAvatar?.animationController || null;
}

function spkmodPatchControllerForMop(controller) {
	if (!controller || typeof controller !== "object" || lunMopPatchedControllers.has(controller)) return;
	lunMopPatchedControllers.add(controller);

	const origSetLocomotion = controller.setLocomotion;
	if (typeof origSetLocomotion === "function") {
		controller.setLocomotion = function (...args) {
			if (window.AutoMopActive && this === spkmodGetLocalAnimController()) {
				return origSetLocomotion.call(this, false);
			}
			return origSetLocomotion.apply(this, args);
		};
	}

	const origExitEmoteIdle = controller.exitEmoteIdle;
	if (typeof origExitEmoteIdle === "function") {
		controller.exitEmoteIdle = function (...args) {
			if (window.AutoMopActive && this === spkmodGetLocalAnimController()) return;
			return origExitEmoteIdle.apply(this, args);
		};
	}
}

function toggleAutoMop(btn) {
	window.AutoMopActive = !window.AutoMopActive;
	const controller = spkmodGetLocalAnimController();
	if (window.AutoMopActive) {
		if (controller) {
			spkmodPatchControllerForMop(controller);
			if (typeof controller.playEmote === "function") {
				controller.playEmote();
			} else if (typeof controller.enterEmoteIdle === "function") {
				controller.enterEmoteIdle();
			}
		}
	} else if (controller) {
		if (typeof controller.exitEmoteIdle === "function") controller.exitEmoteIdle();
		else if (typeof controller.crossFadeToLocomotion === "function") controller.crossFadeToLocomotion();
	}
	const targetBtn = btn || (typeof lunPanelElements !== "undefined" && lunPanelElements.autoMopBtn);
	if (targetBtn) {
		setText(targetBtn, t(window.AutoMopActive ? "autoMopOn" : "autoMopOff") || (window.AutoMopActive ? "Mop: ⏸️" : "Mop: ▶️"));
	}
}

window.LocalBurgerSkinMode = 0; // Legacy compatibility flag mirrored by 22_skins.js

function getBurgerSkinBtnLabel() {
	const idx = window.LocalBurgerSkinMode || 0;
	return t(LUN_BURGER_SKIN_KEYS[idx]) || LUN_BURGER_SKIN_FALLBACKS[idx];
}

function cycleBurgerSkin() {
	const nextMode = ((window.LocalBurgerSkinMode || 0) + 1) % LUN_BURGER_SKIN_CODES.length;
	const targetSkinId = nextMode === 1 ? "costume_burger_staff_a" : (nextMode === 2 ? "costume_burger_staff_b" : null);
	if (window.spkmodSkins && typeof window.spkmodSkins.equip === "function") {
		if (targetSkinId) window.spkmodSkins.equip(targetSkinId);
		else window.spkmodSkins.unequip();
	}
}

window.BurgerCarMode = 0; // Active vehicle code mirrored by 26_vehicles.js (0 = Off, 1 = Sedan, 2 = Van, 3..19 = Vehicles)
window.BurgerCarColorIdx = 0;
const SPKMOD_BURGER_CAR_SCALE = 1.22;
let _lunBurgerCarGltfScene = null;
let _lunBurgerCarLoadingPromise = null;

function spkmodIsCarSystemEnabled() {
	return window.spkmodCarSystemEnabled !== false;
}

function spkmodGetCarEnabledToastText() {
	return (typeof t === "function" && t("carSystemEnabledToast")) || "🚗 Vehicles display & sync enabled.";
}

function spkmodGetCarDisabledToastText() {
	return (typeof t === "function" && t("carSystemDisabledToast")) || "🚗 Vehicles display & sync is disabled. Enable it in Settings (under Pets).";
}

function spkmodPlayBurgerCarAudio(sfxPath, gainMultiplier = 1) {
	try {
		const gainScale = Number.isFinite(gainMultiplier) ? Math.max(0, Math.min(1, gainMultiplier)) : 1;
		if (gainScale <= 0.001) return;
		const sfxVol = typeof window.spkmodGetEffectiveSfxVolume === "function"
			? window.spkmodGetEffectiveSfxVolume()
			: ((typeof isGameMuted === "function" && isGameMuted()) ? 0 : 0.5);
		if (sfxVol <= 0.001) return;
		const audio = new Audio(sfxPath);
		audio.volume = Math.max(0, Math.min(1, sfxVol * 0.65 * gainScale));
		audio.play().catch(() => {});
	} catch (_) {}
}

function spkmodHasActiveNativeMount(container, playerId) {
	try {
		const entries = typeof gameState !== "undefined" ? gameState?.mountVisuals?.entries : null;
		if (!entries) return false;
		if (playerId != null && playerId !== "") {
			if (entries.has(playerId) || entries.has(Number(playerId)) || entries.has(String(playerId))) {
				return true;
			}
		}
		if (container) {
			for (const entry of entries.values()) {
				if (entry && entry.cartGroup && entry.cartGroup.parent === container) {
					return true;
				}
			}
		}
	} catch (_) {}
	return false;
}

function spkmodSetNativeCartVisible(container, playerId, visible) {
	try {
		const entries = typeof gameState !== "undefined" ? gameState?.mountVisuals?.entries : null;
		if (!entries) return;
		const visited = new Set();
		const applyEntry = (entry) => {
			if (!entry || !entry.cartGroup || visited.has(entry.cartGroup)) return;
			visited.add(entry.cartGroup);
			entry.cartGroup.visible = !!visible;
			entry.cartGroup.__spkmodHiddenByCar = !visible;
		};
		if (playerId != null && playerId !== "") {
			const keys = [playerId, Number(playerId), String(playerId)];
			for (const k of keys) {
				const e = entries.get(k);
				if (e) applyEntry(e);
			}
		}
		if (container) {
			for (const entry of entries.values()) {
				if (entry && entry.cartGroup && entry.cartGroup.parent === container) {
					applyEntry(entry);
				}
			}
		}
	} catch (_) {}
}

async function spkmodLoadBurgerVehiclesScene() {
	if (_lunBurgerCarGltfScene) return _lunBurgerCarGltfScene;
	if (_lunBurgerCarLoadingPromise) return _lunBurgerCarLoadingPromise;
	_lunBurgerCarLoadingPromise = (async () => {
		if (typeof spkmodEnsureGLTFLoader !== "function") return null;
		const GLTFLoader = await spkmodEnsureGLTFLoader();
		if (!GLTFLoader) return null;
		const loader = new GLTFLoader();
		const meshopt = (typeof _spkmodMeshoptDecoder !== "undefined" && _spkmodMeshoptDecoder) || window.THREE?.MeshoptDecoder;
		if (meshopt) {
			if (meshopt.ready) await meshopt.ready;
			loader.setMeshoptDecoder(meshopt);
		}
		const gltf = await loader.loadAsync("/models/burger_shop/burger-shop-vehicles.glb");
		_lunBurgerCarGltfScene = gltf?.scene || null;
		return _lunBurgerCarGltfScene;
	})().finally(() => {
		_lunBurgerCarLoadingPromise = null;
	});
	return _lunBurgerCarLoadingPromise;
}

function spkmodCreateBurgerCarInstance(scene, modelName, colorHex) {
	const prefab = scene.getObjectByName(modelName);
	if (!prefab) return null;

	const carObj = prefab.clone(true);
	carObj.scale.multiplyScalar(SPKMOD_BURGER_CAR_SCALE);
	carObj.traverse(node => {
		if (node.isMesh && node.material) {
			const mats = Array.isArray(node.material) ? node.material : [node.material];
			const replaced = mats.map(m => {
				if (m && m.name === "car_body") {
					const cloned = m.clone();
					if (cloned.color) cloned.color.setHex(colorHex);
					return cloned;
				}
				return m;
			});
			node.material = Array.isArray(node.material) ? replaced : replaced[0];
		}
	});

	const isVan = modelName === "Vehicle_Van";
	const wheelRadius = (isVan ? 0.34 : 0.36) * SPKMOD_BURGER_CAR_SCALE;
	const seatOffsetY = isVan ? 1.72 : 1.30;
	const wheels = ["FL", "FR", "RL", "RR"]
		.map(suffix => carObj.getObjectByName(`${modelName}_Wheel_${suffix}`))
		.filter(Boolean);

	return { carObj, wheelRadius, seatOffsetY, wheels };
}

function cycleBurgerCar() {
	if (typeof window.spkmodToggleVehiclesModal === "function") {
		window.spkmodToggleVehiclesModal();
	}
}

let _lunEveryoneCarsState = null;
let _lunEveryoneCarsGen = 0;

window.spkmodResetCarsEveryone = function(silent = false, clearLocalCar = true) {
	_lunEveryoneCarsGen++;
	if (_lunEveryoneCarsState) {
		if (_lunEveryoneCarsState.rafId) cancelAnimationFrame(_lunEveryoneCarsState.rafId);
		for (const entry of _lunEveryoneCarsState.entries) {
			if (entry.root && entry.root.parent) {
				entry.root.parent.remove(entry.root);
			}
			spkmodSetNativeCartVisible(entry.container, entry.playerId, true);
			if (!spkmodHasActiveNativeMount(entry.container, entry.playerId)) {
				if (entry.posePos) {
					entry.posePos.set(0, entry.origY || 0, 0);
				}
				if (entry.ctrl && typeof entry.ctrl.exitMountPose === "function") {
					try { entry.ctrl.exitMountPose(); } catch (_) {}
				}
			}
		}
		_lunEveryoneCarsState = null;
	}

	const sweepContainer = container => {
		if (!container || typeof container.children === "undefined") return;
		for (let i = container.children.length - 1; i >= 0; i--) {
			const child = container.children[i];
			if (child && child.name === "spkmod_everyone_car") {
				container.remove(child);
			}
		}
	};

	if (typeof gameState !== "undefined" && gameState) {
		sweepContainer(gameState.playerContainer);
		if (gameState.remotePlayers?.remotePlayers) {
			for (const [k, rp] of gameState.remotePlayers.remotePlayers) {
				sweepContainer(rp?.container);
				const hasRemoteVeh = typeof window.spkmodHasRemoteVehicle === "function" && window.spkmodHasRemoteVehicle(String(k));
				if (!hasRemoteVeh) {
					spkmodSetNativeCartVisible(rp?.container, k, true);
					if (!spkmodHasActiveNativeMount(rp?.container, k)) {
						const posePos = rp?.avatarPose?.position || rp?.avatar?.root?.position;
						if (posePos && posePos.y !== 0) posePos.set(0, 0, 0);
						const ctrl = rp?.avatar?.animationController || rp?.container?.controller;
						if (ctrl && typeof ctrl.exitMountPose === "function") {
							try { ctrl.exitMountPose(); } catch (_) {}
						}
					}
				}
			}
		}
	}

	if (clearLocalCar) {
		if (window.spkmodVehicles && typeof window.spkmodVehicles.unequip === "function") {
			window.spkmodVehicles.unequip(true, true);
		} else {
			window.BurgerCarMode = 0;
		}
	}

	if (!silent && typeof chatLog === "function") {
		chatLog("🚗 Reset all cars.");
	}
};

window.spkmodRandomCarsEveryone = async function() {
	if (!spkmodIsCarSystemEnabled()) {
		if (typeof chatLog === "function") {
			chatLog(spkmodGetCarDisabledToastText());
		}
		return;
	}
	window.spkmodResetCarsEveryone(true, true);
	const gen = ++_lunEveryoneCarsGen;
	const scene = await spkmodLoadBurgerVehiclesScene();
	if (!scene || gen !== _lunEveryoneCarsGen) return;
	if (typeof gameState === "undefined" || !gameState) return;

	const modelNames = LUN_BURGER_CAR_MODES.slice(1).filter(Boolean);
	if (!modelNames.length || !LUN_BURGER_CAR_COLORS.length) return;

	const entries = [];
	const attachCar = (container, posePos, ctrl, playerId) => {
		if (!container) return;
		const modelName = modelNames[Math.floor(Math.random() * modelNames.length)];
		const colorHex = LUN_BURGER_CAR_COLORS[Math.floor(Math.random() * LUN_BURGER_CAR_COLORS.length)];
		const inst = spkmodCreateBurgerCarInstance(scene, modelName, colorHex);
		if (!inst) return;

		const { carObj, wheelRadius, seatOffsetY, wheels } = inst;
		carObj.name = "spkmod_everyone_car";
		container.add(carObj);
		spkmodSetNativeCartVisible(container, playerId, false);

		const origY = posePos ? posePos.y : 0;
		if (posePos) posePos.set(0, seatOffsetY, 0);
		if (ctrl && typeof ctrl.enterMountPose === "function") {
			try { ctrl.enterMountPose("sit"); } catch (_) {}
		}

		entries.push({
			container,
			playerId,
			posePos,
			ctrl,
			root: carObj,
			wheels,
			wheelRadius,
			seatOffsetY,
			origY,
			lastX: container.position ? container.position.x : 0,
			lastZ: container.position ? container.position.z : 0
		});
	};

	if (gameState.playerContainer) {
		attachCar(
			gameState.playerContainer,
			gameState.localAvatarPose?.position || null,
			spkmodGetLocalAnimController(),
			gameState.myPlayerId
		);
	}

	if (gameState.remotePlayers?.remotePlayers) {
		for (const [k, rp] of gameState.remotePlayers.remotePlayers) {
			if (!rp || !rp.container) continue;
			if (typeof window.spkmodHasRemoteVehicle === "function" && window.spkmodHasRemoteVehicle(String(k))) continue;
			attachCar(
				rp.container,
				rp.avatarPose?.position || rp.avatar?.root?.position || null,
				rp.avatar?.animationController || rp.container?.controller || null,
				k
			);
		}
	}

	if (!entries.length) return;

	const state = { entries, rafId: 0 };
	_lunEveryoneCarsState = state;

	const tick = () => {
		if (_lunEveryoneCarsState !== state) return;
		for (const entry of state.entries) {
			if (!entry.container) continue;
			if (entry.root.parent !== entry.container) {
				entry.container.add(entry.root);
			}
			spkmodSetNativeCartVisible(entry.container, entry.playerId, false);
			if (entry.posePos) {
				entry.posePos.set(0, entry.seatOffsetY, 0);
			}
			if (entry.ctrl && !entry.ctrl.mountSitPlaying && typeof entry.ctrl.enterMountPose === "function") {
				try { entry.ctrl.enterMountPose("sit"); } catch (_) {}
			}
			if (entry.container.position) {
				const dx = entry.container.position.x - entry.lastX;
				const dz = entry.container.position.z - entry.lastZ;
				const dist = Math.hypot(dx, dz);
				if (dist > 0.0001) {
					const angle = dist / entry.wheelRadius;
					for (const w of entry.wheels) w.rotation.x += angle;
					entry.lastX = entry.container.position.x;
					entry.lastZ = entry.container.position.z;
				}
			}
		}
		state.rafId = requestAnimationFrame(tick);
	};
	state.rafId = requestAnimationFrame(tick);

	if (typeof chatLog === "function") {
		chatLog(`🚗 Gave random cars to ${entries.length} player(s)!`);
	}
};

window.PetDanceActive = false;
let petDanceInterval = null;
let petDanceTick = 0;

function petDanceLoop() {
	if (!window.PetDanceActive) return;
	
	petDanceTick++;
	
	if (petDanceTick % 7 === 0) {
		if (typeof gameState !== "undefined" && gameState?.sendEmoteNow) {
			gameState.sendEmoteNow(Emotes.StrokeBloom);
		}
	}
	
	if (petDanceTick % 90 === 0) {
		if (typeof gameState !== "undefined" && gameState?.sendEmoteNow) {
			gameState.sendEmoteNow(Emotes.Dance);
		}
	}
}

function togglePetDance(btn) {
	window.PetDanceActive = !window.PetDanceActive;
	if (window.PetDanceActive) {
		petDanceTick = 0;
		if (petDanceInterval) clearInterval(petDanceInterval);
		petDanceInterval = setInterval(petDanceLoop, 100);
		
		if (!window.AutoHeartsActive) {
			window.AutoHeartsActive = true;
			chatLog(t("autoHeartsActivatedMsg") || "Auto Hearts activated!");
			if (typeof autoHeartsLoop === "function") autoHeartsLoop();
			const heartsBtn = typeof lunPanelElements !== "undefined" ? lunPanelElements.autoHeartsBtn : null;
			if (heartsBtn) setText(heartsBtn, t("autoHeartsOn") || "Auto Hearts: ON");
		}
		
		if (typeof gameState !== "undefined" && gameState?.sendEmoteNow) {
			gameState.sendEmoteNow(Emotes.Dance);
		}
		
		chatLog(t("petDanceActivatedMsg") || "Pet Dance combo activated!");
		chatLog(t("petDanceReminderMsg") || "Note: The petting combo is only fully visible to other players!");
	} else {
		if (petDanceInterval) {
			clearInterval(petDanceInterval);
			petDanceInterval = null;
		}
		// Disable auto hearts when pet dance is turned off
		if (window.AutoHeartsActive) {
			window.AutoHeartsActive = false;
			clearTimeout(window.__autoHeartsTimeoutId);
			const heartsBtn = typeof lunPanelElements !== "undefined" ? lunPanelElements.autoHeartsBtn : null;
			if (heartsBtn) setText(heartsBtn, t("autoHeartsOff") || "Auto Hearts: OFF");
		}
		
		chatLog(t("petDanceDeactivatedMsg") || "Pet Dance deactivated.");
	}
	
	const targetBtn = btn || (typeof lunPanelElements !== "undefined" && lunPanelElements.petDanceBtn);
	if (targetBtn) {
		setText(targetBtn, t(window.PetDanceActive ? "petDanceOn" : "petDanceOff") || (window.PetDanceActive ? "Pet Dance: ⏸️" : "Pet Dance: ▶️"));
	}
}

window.JustPetActive = false;
let justPetInterval = null;
let justPetTick = 0;

function justPetLoop() {
	if (!window.JustPetActive) return;
	
	justPetTick++;
	
	// Cycle between StrokeStart (4) and StrokeStage2 (5) every 1.5 seconds to keep the petting face active
	if (justPetTick % 30 === 15) {
		if (typeof gameState !== "undefined" && gameState?.sendEmoteNow) {
			gameState.sendEmoteNow(Emotes.StrokeStage2);
		}
	} else if (justPetTick % 30 === 0) {
		if (typeof gameState !== "undefined" && gameState?.sendEmoteNow) {
			gameState.sendEmoteNow(Emotes.StrokeStart);
		}
	}
}

function toggleJustPet(btn) {
	window.JustPetActive = !window.JustPetActive;
	if (window.JustPetActive) {
		justPetTick = 0;
		if (justPetInterval) clearInterval(justPetInterval);
		justPetInterval = setInterval(justPetLoop, 100);
		
		// Immediately trigger the petting facial expression (StrokeStart = 4)
		if (typeof gameState !== "undefined" && gameState?.sendEmoteNow) {
			gameState.sendEmoteNow(Emotes.StrokeStart);
		}
		
		chatLog(t("justPetActivatedMsg") || "Just Pet activated!");
	} else {
		if (justPetInterval) {
			clearInterval(justPetInterval);
			justPetInterval = null;
		}
		
		// Send StrokeCancel (7) to return Speaki's facial expression back to normal
		if (typeof gameState !== "undefined" && gameState?.sendEmoteNow) {
			gameState.sendEmoteNow(Emotes.StrokeCancel);
		}
		
		chatLog(t("justPetDeactivatedMsg") || "Just Pet deactivated.");
	}
	
	const targetBtn = btn || (typeof lunPanelElements !== "undefined" && lunPanelElements.justPetBtn);
	if (targetBtn) {
		setText(targetBtn, t(window.JustPetActive ? "justPetOn" : "justPetOff") || (window.JustPetActive ? "Just Pet: ⏸️" : "Just Pet: ▶️"));
	}
}



window.RitualState = 0;
