// ============================================================================
// BURGER SHOP BIG-ORDER WIDE ("FAT") CUSTOMERS
// ============================================================================
var spkmodCA = {
	on: typeof window !== "undefined" ? window.spkmodBurgerFatCustomersEnabled !== false : true,
	fx: 2,
	fz: 2,
	list: [],
	t: 0,
	tScan: 0,
	bubbles: [],
	need: ["Burger_Basic", "Potato_Cooked", "Drink_Prepped"],
	sprites: 1,
	visible: true,
	every: 100,
	window: 3000,
	log: false,
	pelvis: /pelvis|hip/i,
	head: /head/i,
	spine: /spine/i
};
if (typeof window !== "undefined") window.spkmodCA = spkmodCA;

let _spkmodCAMatH1 = null;
let _spkmodCAMatInv = null;
const _spkmodCAPropMats = [];

function spkmodCACollectHandProps(e) {
	const out = [];
	const hands = e && e.hands;
	if (!hands) return out;
	for (let i = 0; i < hands.length; i++) {
		const hb = hands[i];
		const ch = hb && hb.children;
		if (!ch) continue;
		for (let j = 0; j < ch.length; j++) {
			const c = ch[j];
			if (c && c.userData && c.userData.lunchPropHolder === true) {
				out.push(c);
			}
		}
	}
	return out;
}

function spkmodCARestorePropHolders(e) {
	const props = spkmodCACollectHandProps(e);
	for (let i = 0; i < props.length; i++) {
		const h = props[i];
		h.matrixAutoUpdate = true;
		h.updateMatrix();
	}
}

function spkmodCAContainers() {
	const gs = typeof gameState !== "undefined" ? gameState : (typeof window !== "undefined" ? window.gameState : null);
	const c = gs && gs.burgerShop && gs.burgerShop.customers;
	if (!c) return [];
	const list = Array.isArray(c) ? c : (typeof c.values === "function" ? [...c.values()] : Object.values(c));
	return list.map(e => e && e.container).filter(Boolean);
}

function spkmodCAAxes(bone, cont) {
	const B = bone.matrixWorld.elements, C = cont.matrixWorld.elements;
	const n = (e, o) => {
		const l = Math.hypot(e[o], e[o + 1], e[o + 2]) || 1;
		return [e[o] / l, e[o + 1] / l, e[o + 2] / l];
	};
	const axes = ["x", "y", "z"];
	const cx = n(C, 0), cy = n(C, 4), cz = n(C, 8);
	const pick = (c, exclude) => {
		let best = "x", bd = -1;
		for (let k = 0; k < 3; k++) {
			const a = axes[k];
			if (a === exclude) continue;
			const b = n(B, k * 4);
			const d = Math.abs(b[0] * c[0] + b[1] * c[1] + b[2] * c[2]);
			if (d > bd) { bd = d; best = a; }
		}
		return best;
	};
	let ax = pick(cx);
	let az = pick(cz);
	if (ax === az) {
		const ay = pick(cy);
		ax = pick(cx, ay);
		az = pick(cz, ax === ay ? ay : ax);
		if (az === ay) az = axes.find(a => a !== ax && a !== ay) || az;
	}
	return { x: ax, z: az };
}

function spkmodCAVisible(o, stop) {
	let hitStop = false;
	for (let x = o; x; x = x.parent) {
		if (x === stop) { hitStop = true; break; }
		if (!x.visible) return false;
	}
	return stop ? hitStop : true;
}

function spkmodCARead(e, scene) {
	const S = spkmodCA, names = new Set();
	let sprites = 0;
	const walk = root => root.traverse(o => {
		if (S.visible && !spkmodCAVisible(o, scene)) return;
		if (o.isSprite) sprites++;
		else if (o.isMesh && o.name) names.add(o.name);
	});
	walk(e.cont);
	for (const b of (e.bub || [])) walk(b);
	return { names, sprites };
}

function spkmodCAInside(o, r) {
	for (let x = o; x; x = x.parent) {
		if (x === r) return true;
	}
	return false;
}

function spkmodCARelease(e) {
	if (!e || e.rel) return;
	e.rel = true;
	if (e.pel) {
		e.pel.scale[e.ap.x] = e.p0.x;
		e.pel.scale[e.ap.z] = e.p0.z;
		e.pel.updateMatrix();
	}
	if (e.head) {
		e.head.matrixAutoUpdate = true;
		e.head.updateMatrix();
	}
	spkmodCARestorePropHolders(e);
	if (e.cont) {
		e.cont.updateMatrixWorld(true);
	}
}

function spkmodCAReleaseAll() {
	const S = spkmodCA;
	for (const e of S.list) spkmodCARelease(e);
	S.list = [];
	S.bubbles = [];
	S.tScan = 0;
}

function spkmodCASync(scene) {
	const S = spkmodCA, now = performance.now();
	const conts = spkmodCAContainers();
	if (conts.length === 0) {
		if (S.list.length > 0 || S.bubbles.length > 0) spkmodCAReleaseAll();
		return;
	}
	if (now - S.tScan > 1000) {
		S.tScan = now;
		S.bubbles = [];
		const byRoot = new Map();
		scene.traverse(o => {
			if (o.isMesh && o.geometry && o.geometry.type === "ShapeGeometry" && o.parent && o.parent.parent && o.parent.parent.parent) {
				const r = o.parent.parent.parent;
				let entry = byRoot.get(r);
				if (!entry) {
					entry = { root: r, shapes: [] };
					byRoot.set(r, entry);
					S.bubbles.push(entry);
				}
				entry.shapes.push(o);
			}
		});
	}
	const own = new Map();
	const hasBubbleSet = new Set();
	for (const b of S.bubbles) {
		const root = b.root;
		if (!spkmodCAInside(root, scene)) continue;
		const bVis = !S.visible || b.shapes.some(sh => spkmodCAVisible(sh, scene));
		let nested = false;
		for (const c of conts) {
			if (spkmodCAInside(root, c)) {
				nested = true;
				if (bVis) hasBubbleSet.add(c);
				break;
			}
			if (spkmodCAInside(c, root)) {
				nested = true;
				break;
			}
		}
		if (nested) continue;
		let best = null, bd = 1.2;
		const a = root.matrixWorld.elements;
		for (const c of conts) {
			const m = c.matrixWorld.elements;
			const d = Math.hypot(a[12] - m[12], a[14] - m[14]);
			if (d < bd) { bd = d; best = c; }
		}
		if (best) {
			if (!own.has(best)) own.set(best, []);
			own.get(best).push(root);
			if (bVis) hasBubbleSet.add(best);
		}
	}
	const keep = [];
	for (const cont of conts) {
		let e = S.list.find(x => x.cont === cont);
		if (!e) {
			const B = [];
			cont.traverse(o => { if (o.isBone) B.push(o); });
			const pel = B.find(b => S.pelvis.test(b.name)) || B.find(b => S.spine.test(b.name));
			const head = B.find(b => S.head.test(b.name) && !/nub/i.test(b.name));
			if (!pel || !head || pel === head || !head.parent) continue;
			const hands = B.filter(b => /hand/i.test(b.name) && !/nub/i.test(b.name));
			cont.updateMatrixWorld(true);
			const ap = spkmodCAAxes(pel, cont);
			const px = pel.scale[ap.x], pz = pel.scale[ap.z];
			if (!px || !pz || !isFinite(px) || !isFinite(pz)) continue;
			e = { cont, pel, head, hands, ap, p0: { x: px, z: pz }, M: head.matrix.constructor, want: false, rel: true, seen: null, decided: false, born: now, bubbleSeenAt: null };
		}
		if (!e.decided) {
			cont.updateMatrixWorld(true);
			e.bub = own.get(cont) || [];
			const r = spkmodCARead(e, scene);
			e.seen = r;
			const hit = S.need.every(n => r.names.has(n)) && r.sprites >= S.sprites;
			if (hit) {
				e.decided = true;
				e.want = true;
				if (S.log) console.log("[SpeakiMod] customer decided: WIDE", [...r.names].filter(n => !/^(Mesh_|geometry_|Cap|Rotor|world)/.test(n)).join("+"), "sprites", r.sprites);
			} else {
				const hasBubbleOrOrder = hasBubbleSet.has(cont) || S.need.some(n => r.names.has(n));
				if (hasBubbleOrOrder) {
					if (e.bubbleSeenAt === null) e.bubbleSeenAt = now;
					if (now - e.bubbleSeenAt > S.window) {
						e.decided = true;
						e.want = false;
						if (S.log) console.log("[SpeakiMod] customer decided: normal", [...r.names].filter(n => !/^(Mesh_|geometry_|Cap|Rotor|world)/.test(n)).join("+"), "sprites", r.sprites);
					}
				}
			}
		}
		keep.push(e);
	}
	for (const e of S.list) {
		if (keep.indexOf(e) < 0) spkmodCARelease(e);
	}
	S.list = keep;
}

function spkmodCAApply() {
	const S = spkmodCA;
	for (const e of S.list) {
		const props = spkmodCACollectHandProps(e);
		if (!S.on || !e.want || e.ap.x === e.ap.z) {
			spkmodCARelease(e);
			// Even on normal customers, repair hand tray/food holders whose scale was baked while container.scale < 1 (pop-in race)
			if (S.on && props.length > 0 && e.cont) {
				const ce = e.cont.matrixWorld.elements;
				const contScale = Math.hypot(ce[0], ce[1], ce[2]) || 1;
				for (let i = 0; i < props.length; i++) {
					const h = props[i];
					const hand = h.parent;
					if (!hand) continue;
					const pe = hand.matrixWorld.elements;
					const l0 = Math.hypot(pe[0], pe[1], pe[2]);
					if (l0 > 1e-6 && (Math.abs(h.scale.x * l0 - contScale) > 0.05 * contScale ||
						Math.abs(h.scale.y * l0 - contScale) > 0.05 * contScale ||
						Math.abs(h.scale.z * l0 - contScale) > 0.05 * contScale)) {
						const s = contScale / l0;
						h.scale.x = s;
						h.scale.y = s;
						h.scale.z = s;
						h.updateMatrix();
						h.updateMatrixWorld(true);
					}
				}
			}
			continue;
		}
		const pel = e.pel, head = e.head, neck = head.parent;
		if (!pel || !head || !neck) continue;
		if (!_spkmodCAMatH1 || _spkmodCAMatH1.constructor !== e.M) {
			_spkmodCAMatH1 = new e.M();
			_spkmodCAMatInv = new e.M();
			_spkmodCAPropMats.length = 0;
		}
		e.rel = false;
		head.matrixAutoUpdate = true;
		for (let i = 0; i < props.length; i++) {
			props[i].matrixAutoUpdate = true;
		}
		pel.scale[e.ap.x] = e.p0.x;
		pel.scale[e.ap.z] = e.p0.z;
		pel.updateMatrix();
		e.cont.updateMatrixWorld(true);
		_spkmodCAMatH1.copy(head.matrixWorld);

		// Snapshot rigid unstretched world transforms for hand-held trays / food (child of pelvis -> arm -> hand)
		const ce = e.cont.matrixWorld.elements;
		const contScale = Math.hypot(ce[0], ce[1], ce[2]) || 1;
		let propCount = 0;
		for (let i = 0; i < props.length; i++) {
			const h = props[i];
			const hand = h.parent;
			if (!hand) continue;
			const pe = hand.matrixWorld.elements;
			const l0 = Math.hypot(pe[0], pe[1], pe[2]);
			const l1 = Math.hypot(pe[4], pe[5], pe[6]);
			const l2 = Math.hypot(pe[8], pe[9], pe[10]);
			if (l0 <= 1e-6 || l1 <= 1e-6 || l2 <= 1e-6) continue;
			const idealScale = contScale / l0;
			if (Math.abs(h.scale.x * l0 - contScale) > 0.05 * contScale ||
				Math.abs(h.scale.y * l0 - contScale) > 0.05 * contScale ||
				Math.abs(h.scale.z * l0 - contScale) > 0.05 * contScale) {
				h.scale.x = idealScale;
				h.scale.y = idealScale;
				h.scale.z = idealScale;
				h.updateMatrix();
			}
			let pm = _spkmodCAPropMats[propCount];
			if (!pm || pm.constructor !== e.M) {
				pm = new e.M();
				_spkmodCAPropMats[propCount] = pm;
			}
			const me = pm.elements;
			const s0 = contScale / l0, s1 = contScale / l1, s2 = contScale / l2;
			me[0] = pe[0] * s0; me[1] = pe[1] * s0; me[2] = pe[2] * s0; me[3] = 0;
			me[4] = pe[4] * s1; me[5] = pe[5] * s1; me[6] = pe[6] * s1; me[7] = 0;
			me[8] = pe[8] * s2; me[9] = pe[9] * s2; me[10] = pe[10] * s2; me[11] = 0;
			me[12] = pe[12];    me[13] = pe[13];    me[14] = pe[14];    me[15] = 1;
			props[propCount] = h;
			propCount++;
		}

		pel.scale[e.ap.x] = e.p0.x * S.fx;
		pel.scale[e.ap.z] = e.p0.z * S.fz;
		pel.updateMatrix();
		e.cont.updateMatrixWorld(true);

		const ne = neck.matrixWorld;
		if (typeof ne.determinant !== "function" || Math.abs(ne.determinant()) >= 1e-10) {
			const he = head.matrixWorld.elements;
			_spkmodCAMatH1.elements[12] = he[12];
			_spkmodCAMatH1.elements[13] = he[13];
			_spkmodCAMatH1.elements[14] = he[14];
			head.matrix.copy(_spkmodCAMatInv.copy(ne).invert().multiply(_spkmodCAMatH1));
			head.matrixAutoUpdate = false;
			head.updateMatrixWorld(true);
		}

		for (let i = 0; i < propCount; i++) {
			const h = props[i];
			const hand = h.parent;
			if (!hand) continue;
			const hm = hand.matrixWorld;
			if (typeof hm.determinant === "function" && Math.abs(hm.determinant()) < 1e-10) {
				continue;
			}
			const pm = _spkmodCAPropMats[i];
			const he = hm.elements;
			pm.elements[12] = he[12];
			pm.elements[13] = he[13];
			pm.elements[14] = he[14];
			h.matrix.copy(_spkmodCAMatInv.copy(hm).invert().multiply(pm));
			h.matrixAutoUpdate = false;
			h.updateMatrixWorld(true);
		}
	}
}

function spkmodCARestoreAfterRender() {
	const S = spkmodCA;
	for (const e of S.list) {
		if (!e.rel) {
			spkmodCARelease(e);
		}
	}
}

function spkmodEnsureBurgerFatSceneHook() {
	const gs = typeof gameState !== "undefined" ? gameState : (typeof window !== "undefined" ? window.gameState : null);
	const scene = gs && gs.scene;
	if (!scene) return false;
	if (!scene.__spkmodCABeforeHooked) {
		scene.__spkmodCABeforeHooked = true;
		const prevBefore = scene.onBeforeRender;
		scene.onBeforeRender = function(renderer, sc, camera, ...rest) {
			if (typeof prevBefore === "function") {
				try { prevBefore.call(this, renderer, sc, camera, ...rest); } catch (_) {}
			}
			const curGs = typeof gameState !== "undefined" ? gameState : (typeof window !== "undefined" ? window.gameState : null);
			const S = spkmodCA;
			if (!curGs || sc !== curGs.scene || (!S.on && S.list.length === 0)) return;
			try {
				if (!S.on) {
					spkmodCAReleaseAll();
					return;
				}
				const now = performance.now();
				// Skip order-bubble sync during shader overrideMaterial normal pass (which hides sprites)
				if (!sc.overrideMaterial && now - S.t >= S.every) {
					S.t = now;
					spkmodCASync(sc);
				}
				spkmodCAApply();
			} catch (_) {}
		};
	}
	if (!scene.__spkmodCAAfterFn || scene.onAfterRender !== scene.__spkmodCAAfterFn) {
		// Avoid re-wrapping while shaders or bloom guard temporarily wrap onAfterRender if ours is already in the chain
		const curAfter = scene.onAfterRender;
		if (!curAfter || !curAfter.__spkmodCAInChain) {
			const prevAfter = curAfter;
			const wrappedAfter = function(renderer, sc, camera, ...rest) {
				if (typeof prevAfter === "function") {
					try { prevAfter.call(this, renderer, sc, camera, ...rest); } catch (_) {}
				}
				const curGs = typeof gameState !== "undefined" ? gameState : (typeof window !== "undefined" ? window.gameState : null);
				if (!curGs || sc !== curGs.scene || spkmodCA.list.length === 0) return;
				try {
					spkmodCARestoreAfterRender();
				} catch (_) {}
			};
			wrappedAfter.__spkmodCAInChain = true;
			scene.__spkmodCAAfterFn = wrappedAfter;
			scene.onAfterRender = wrappedAfter;
		}
	}
	return true;
}

window.spkmodSetBurgerFatCustomersEnabled = function(nextEnabled, silentToast = false) {
	const enabled = !!nextEnabled;
	if (typeof window !== "undefined") {
		window.spkmodBurgerFatCustomersEnabled = enabled;
		if (window.localStorage) {
			try {
				localStorage.setItem("spkmod-burger-fat-customers", enabled ? "true" : "false");
			} catch (_) {}
		}
	}
	spkmodCA.on = enabled;
	if (typeof lunPanelElements !== "undefined" && lunPanelElements && lunPanelElements.burgerFatCustomersToggleInput) {
		lunPanelElements.burgerFatCustomersToggleInput.checked = enabled;
	}
	if (enabled) {
		spkmodCA.t = 0;
		spkmodCA.tScan = 0;
		spkmodEnsureBurgerFatSceneHook();
	} else {
		spkmodCAReleaseAll();
	}
	if (!silentToast && typeof chatLog === "function") {
		const msg = enabled
			? (typeof tCustom === "function" ? tCustom("burgerFatCustomersEnabledToast", "🍔 Fat Burger Shop Customers enabled.") : "🍔 Fat Burger Shop Customers enabled.")
			: (typeof tCustom === "function" ? tCustom("burgerFatCustomersDisabledToast", "🍔 Fat Burger Shop Customers disabled.") : "🍔 Fat Burger Shop Customers disabled.");
		chatLog(msg);
	}
	return enabled;
};

function spkmodCustomerAuto(on, fx, fz) {
	if (fx) {
		spkmodCA.fx = fx;
		spkmodCA.fz = fz || fx;
	}
	window.spkmodSetBurgerFatCustomersEnabled(!!on, true);
}
if (typeof window !== "undefined") window.spkmodCustomerAuto = spkmodCustomerAuto;

spkmodEnsureBurgerFatSceneHook();




const mapModalElements = {};
let mapUpdateFrame = null;

// ---- World map viewport (pan / pinch-zoom) ----
// The map is laid out in a fixed logical space (the canvas size, currently 1000x520). On small screens we keep
// that space at a readable scale and show it through a small, pannable window.
let MAP_LW = 1000, MAP_LH = 520; // re-synced from the canvas size right after the map modal is built
// Tune these to change how tall the map window is on small screens.
const MAP_H_RATIO_PORTRAIT = 0.38;  // portrait:  38% of screen height
const MAP_H_RATIO_LANDSCAPE = 0.58; // landscape: 58% of screen height
const MAP_MIN_H = 130;              // never shorter than this (px)
const mapView = { zoom: 1, panX: 0, panY: 0, viewW: MAP_LW, viewH: MAP_LH, dpr: 1, small: false, needCenter: false, needFit: false };

function mapMinZoom() { return Math.min(mapView.viewW / MAP_LW, mapView.viewH / MAP_LH); }

function clampMapPan() {
	const cw = MAP_LW * mapView.zoom, ch = MAP_LH * mapView.zoom, m = 30;
	mapView.panX = cw <= mapView.viewW ? (mapView.viewW - cw) / 2 : Math.max(mapView.viewW - cw - m, Math.min(m, mapView.panX));
	mapView.panY = ch <= mapView.viewH ? (mapView.viewH - ch) / 2 : Math.max(mapView.viewH - ch - m, Math.min(m, mapView.panY));
}

function zoomMapAt(px, py, factor) {
	const nz = Math.max(mapMinZoom(), Math.min(4, mapView.zoom * factor));
	const f = nz / mapView.zoom;
	mapView.panX = px - (px - mapView.panX) * f;
	mapView.panY = py - (py - mapView.panY) * f;
	mapView.zoom = nz;
	clampMapPan();
}

function layoutMapModal() {
	const m = mapModalElements.modalWindow, c = mapModalElements.canvas;
	if (!m || !c) return;
	// Mobile only. On desktop nothing below runs, so the original desktop layout is left untouched.
	const small = typeof spkmodIsMobile === "function" && spkmodIsMobile();
	mapView.small = small;
	if (!small) {
		mapView.viewW = MAP_LW; mapView.viewH = MAP_LH; mapView.dpr = 1;
		mapView.zoom = 1; mapView.panX = 0; mapView.panY = 0;
		return;
	}
	{
		// 📍 / ⤢ buttons and touch-sized close button: mobile only (hidden / original style by default)
		if (mapModalElements.centerBtn) mapModalElements.centerBtn.style.display = "";
		if (mapModalElements.fitBtn) mapModalElements.fitBtn.style.display = "";
		if (mapModalElements.btnRow) mapModalElements.btnRow.style.marginTop = "12px";
		if (mapModalElements.closeBtn) { mapModalElements.closeBtn.style.padding = "8px 20px"; mapModalElements.closeBtn.style.minHeight = "40px"; }
		mapView.dpr = Math.min(window.devicePixelRatio || 1, 2);
		if (window.innerHeight >= window.innerWidth) {
			// Portrait: full width, canvas height = MAP_H_RATIO_PORTRAIT of the screen height.
			mapView.viewW = Math.max(200, Math.min(MAP_LW, window.innerWidth - 24));
			mapView.viewH = Math.max(MAP_MIN_H, Math.min(MAP_LH, Math.round(window.innerHeight * MAP_H_RATIO_PORTRAIT)));
		} else {
			// Landscape: canvas height = MAP_H_RATIO_LANDSCAPE of the screen height, width capped at ~1.92:1.
			mapView.viewH = Math.max(MAP_MIN_H, Math.min(MAP_LH, Math.round(window.innerHeight * MAP_H_RATIO_LANDSCAPE)));
			mapView.viewW = Math.max(200, Math.min(MAP_LW, window.innerWidth - 24, Math.round(mapView.viewH * 1.92)));
		}
		if (mapModalElements.titleLabel) {
			mapModalElements.titleLabel.style.fontSize = "14px";
			mapModalElements.titleLabel.style.marginBottom = "6px";
		}
		m.style.position = "fixed";
		m.style.boxSizing = "border-box";
		m.style.padding = "10px";
		m.style.maxWidth = "calc(100vw - 8px)";
		if (mapView.zoom < mapMinZoom()) mapView.zoom = mapMinZoom();
		clampMapPan();
	}
	c.style.width = mapView.viewW + "px";
	c.style.height = mapView.viewH + "px";
	c.style.maxWidth = "none";
	c.style.touchAction = "none";
	c.width = Math.round(mapView.viewW * mapView.dpr);
	c.height = Math.round(mapView.viewH * mapView.dpr);
	{
		const mw = mapView.viewW + 22;
		if (m.dataset.userDragged !== "true") {
			m.style.left = Math.max(4, (window.innerWidth - mw) / 2) + "px";
			m.style.top = "8px";
		} else {
			const r = m.getBoundingClientRect();
			m.style.left = Math.max(0, Math.min(r.left, window.innerWidth - mw)) + "px";
			m.style.top = Math.max(0, Math.min(r.top, window.innerHeight - 60)) + "px";
		}
	}
}

function initMapGestures() {
	const c = mapModalElements.canvas;
	if (!c || c.__spkmodGestures) return;
	c.__spkmodGestures = true;
	const ptrs = new Map();
	let lastDist = 0, lastMid = null;
	const local = e => { const r = c.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; };
	const stop = e => { e.stopPropagation(); };
	c.addEventListener("pointerdown", e => {
		if (!mapView.small) return;
		stop(e);
		try { c.setPointerCapture(e.pointerId); } catch (_) {}
		ptrs.set(e.pointerId, local(e));
		lastDist = 0; lastMid = null;
	});
	c.addEventListener("pointermove", e => {
		if (!mapView.small || !ptrs.has(e.pointerId)) return;
		stop(e);
		const prev = ptrs.get(e.pointerId), cur = local(e);
		ptrs.set(e.pointerId, cur);
		if (ptrs.size === 1) {
			mapView.panX += cur.x - prev.x;
			mapView.panY += cur.y - prev.y;
			clampMapPan();
		} else if (ptrs.size === 2) {
			const [a, b] = [...ptrs.values()];
			const dist = Math.hypot(a.x - b.x, a.y - b.y) || 1;
			const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
			if (lastDist) {
				mapView.panX += mid.x - lastMid.x;
				mapView.panY += mid.y - lastMid.y;
				zoomMapAt(mid.x, mid.y, dist / lastDist);
			}
			lastDist = dist; lastMid = mid;
		}
	});
	const up = e => { stop(e); ptrs.delete(e.pointerId); lastDist = 0; lastMid = null; };
	c.addEventListener("pointerup", up);
	c.addEventListener("pointercancel", up);
	c.addEventListener("wheel", e => {
		if (!mapView.small) return;
		e.preventDefault(); e.stopPropagation();
		const p = local(e);
		zoomMapAt(p.x, p.y, Math.exp(-e.deltaY * 0.0015));
	}, { passive: false });
}

window.addEventListener("resize", () => {
	if (mapView.small && mapModalElements.modalWindow && mapModalElements.modalWindow.style.display !== "none") {
		layoutMapModal();
		mapView.needCenter = true;
	}
});

function openMapModal() {
	mapModalElements.modalWindow.style.display = "flex";
	layoutMapModal();
	if (mapView.small) {
		initMapGestures();
		mapView.zoom = Math.max(mapMinZoom(), 1);
		mapView.needCenter = true;
	}
	updateMapLoop();
}

function closeMapModal() {
	mapModalElements.modalWindow.style.display = "none";
	if (mapUpdateFrame) cancelAnimationFrame(mapUpdateFrame);
	mapUpdateFrame = null;
}

function toggleMapModal() {
	if (!mapModalElements.modalWindow) return;
	if (mapModalElements.modalWindow.style.display === "none") {
		openMapModal();
	} else {
		closeMapModal();
	}
}

function updateMapLoop() {
	if (!mapModalElements.canvas || mapModalElements.modalWindow.style.display === "none") {
		mapUpdateFrame = null;
		return;
	}
	const ctx = mapModalElements.canvas.getContext("2d");
	const w = MAP_LW;
	const h = MAP_LH;
	
	ctx.setTransform(1, 0, 0, 1, 0, 0);
	ctx.clearRect(0, 0, mapModalElements.canvas.width, mapModalElements.canvas.height);
	
	const padding = 20;
	const drawW = w - padding * 2;
	const drawH = h - padding * 2;
	
	const connectedZones = new Set();
	for (const src in Portals) {
		connectedZones.add(parseInt(src));
		for (const tgt in Portals[src]) {
			connectedZones.add(parseInt(tgt));
		}
	}

	let rows = [[], [], [], []];
	const allZones = (typeof window !== "undefined" && window.WorldZones) ? window.WorldZones : (typeof WorldZones !== "undefined" ? WorldZones : []);
	for (const zone of allZones) {
		if (!connectedZones.has(zone.zoneId)) continue;
		const cz = (zone.minZ + zone.maxZ) / 2;
		if (cz < -500) rows[0].push(zone);      // World 4: Thunder/Mist (Zones 301-309, Z ~ -850)
		else if (cz <= 0) rows[1].push(zone);   // World 3: Core/Underground (Zones 201-209, Z ~ -100)
		else if (cz <= 200) rows[2].push(zone); // World 1: Overworld (Zones 1-10, Z ~ 100)
		else rows[3].push(zone);                // World 2: World Tree (Zones 101-108, Z ~ 300)
	}
	
	rows.forEach(r => r.sort((a,b) => ((a.minX+a.maxX)/2) - ((b.minX+b.maxX)/2)));
	
	const zonePos = {};
	const boxW = 66;
	const boxH = 36;
	
	const activeRows = rows.map((r, idx) => ({ row: r, idx })).filter(item => item.row.length > 0);
	const totalActive = activeRows.length || 1;
	const rowSpacingY = totalActive > 1 ? (drawH - boxH) / (totalActive - 1) : 0;
	
	for (let i = 0; i < activeRows.length; i++) {
		const rList = activeRows[i].row;
		let spacingX = drawW / rList.length;
		for (let j = 0; j < rList.length; j++) {
			let z = rList[j];
			zonePos[z.zoneId] = {
				x: padding + j * spacingX + spacingX/2,
				y: padding + boxH/2 + i * rowSpacingY,
				zone: z
			};
		}
	}
	
	const getLogicalPos = (zid, px, pz) => {
		const zp = zonePos[zid];
		if (!zp) return null;
		const z = zp.zone;
		let pctX = (px - z.minX) / (z.maxX - z.minX);
		let pctZ = (pz - z.minZ) / (z.maxZ - z.minZ);
		pctX = Math.max(0, Math.min(1, pctX));
		pctZ = Math.max(0, Math.min(1, pctZ));
		return {
			x: zp.x - boxW/2 + pctX * boxW,
			y: zp.y - boxH/2 + pctZ * boxH
		};
	};

	if (mapView.needFit) {
		mapView.zoom = mapMinZoom();
		mapView.needFit = false;
		clampMapPan();
	}
	if (mapView.needCenter && mapView.small) {
		const cz = gameState && gameState.zoneId ? gameState.zoneId % 10000 : null;
		let target = cz !== null && zonePos[cz] ? zonePos[cz] : null;
		if (target && gameState.playerContainer) {
			const lp = getLogicalPos(cz, gameState.playerContainer.position.x, gameState.playerContainer.position.z);
			if (lp) target = lp;
		}
		if (target) {
			mapView.panX = mapView.viewW / 2 - target.x * mapView.zoom;
			mapView.panY = mapView.viewH / 2 - target.y * mapView.zoom;
			clampMapPan();
		}
		mapView.needCenter = false;
	}
	ctx.setTransform(mapView.dpr * mapView.zoom, 0, 0, mapView.dpr * mapView.zoom, mapView.dpr * mapView.panX, mapView.dpr * mapView.panY);

	ctx.strokeStyle = "rgba(255, 200, 50, 0.4)";
	ctx.lineWidth = 1.5;
	const drawnConnections = new Set();
	for (const src in Portals) {
		for (const tgt in Portals[src]) {
			const pairKey = parseInt(src) < parseInt(tgt) ? `${src}-${tgt}` : `${tgt}-${src}`;
			if (drawnConnections.has(pairKey)) continue;

			if (Portals[tgt] && Portals[tgt][src] && zonePos[src] && zonePos[tgt]) {
				drawnConnections.add(pairKey);
				const p1 = zonePos[src];
				const p2 = zonePos[tgt];
				const pInfo1 = Portals[src][tgt];
				const pInfo2 = Portals[tgt][src];
				
				if (pInfo1 && pInfo2) {
					const lPos1 = getLogicalPos(parseInt(src), pInfo1.pos.x, pInfo1.pos.z);
					const lPos2 = getLogicalPos(parseInt(tgt), pInfo2.pos.x, pInfo2.pos.z);
					
					if (lPos1 && lPos2) {
						ctx.beginPath();
						ctx.moveTo(lPos1.x, lPos1.y);
						
						const dy = Math.abs(p1.y - p2.y);
						if (dy > 10) {
							// If connecting across non-adjacent rows (e.g. World 1 to World 4 skipping over World 3),
							// route through the left margin track so it doesn't slice through intermediate zone boxes!
							if (dy > rowSpacingY * 1.5) {
								const lowerPos = p1.y > p2.y ? lPos1 : lPos2;
								const upperPos = p1.y > p2.y ? lPos2 : lPos1;
								const lowerZone = p1.y > p2.y ? p1 : p2;
								const gapY = lowerZone.y - boxH/2 - (rowSpacingY - boxH) / 2;
								const marginTrackX = 14;

								ctx.lineTo(lowerPos.x, gapY);
								ctx.lineTo(marginTrackX, gapY);
								ctx.lineTo(marginTrackX, upperPos.y);
								ctx.lineTo(upperPos.x, upperPos.y);
							} else {
								const midY = (lPos1.y + lPos2.y) / 2;
								ctx.lineTo(lPos1.x, midY);
								ctx.lineTo(lPos2.x, midY);
								ctx.lineTo(lPos2.x, lPos2.y);
							}
						} else {
							ctx.lineTo(lPos2.x, lPos2.y);
						}
						ctx.stroke();
					}
				}
			}
		}
	}
	

	for (const zid in zonePos) {
		const zp = zonePos[zid];
		const zidNum = parseInt(zid);
		const isCurrent = zidNum === (gameState?.zoneId % 10000);
		const raid = (window.spkmodRaids || []).find(r => r.altarZoneId === zidNum);
		
		const bx = zp.x - boxW/2;
		const by = zp.y - boxH/2;
		
		if (isCurrent) {
			ctx.fillStyle = "rgb(40, 100, 40)";
			ctx.strokeStyle = "rgba(100, 255, 100, 0.8)";
			ctx.lineWidth = 2;
		} else if (raid) {
			ctx.fillStyle = "rgba(45, 25, 25, 0.9)";
			ctx.strokeStyle = "rgba(255, 60, 20, 0.95)";
			ctx.lineWidth = 2.5;
		} else {
			ctx.fillStyle = "rgb(30, 40, 50)";
			ctx.strokeStyle = "rgba(150, 180, 200, 0.6)";
			ctx.lineWidth = 1;
		}
		
		ctx.fillRect(bx, by, boxW, boxH);
		ctx.strokeRect(bx, by, boxW, boxH);
		
		ctx.fillStyle = "white";
		ctx.font = "11px sans-serif";
		ctx.textAlign = "center";
		ctx.textBaseline = "middle";
		
		let rawName = getZoneName(zid);
		
		let words = rawName.split(" ");
		if (words.length > 1) {
			let mid = Math.ceil(words.length / 2);
			let line1 = words.slice(0, mid).join(" ");
			let line2 = words.slice(mid).join(" ");
			ctx.fillText(line1, zp.x, zp.y - 6);
			ctx.fillText(line2, zp.x, zp.y + 6);
		} else {
			ctx.fillText(rawName, zp.x, zp.y);
		}

		if (raid) {
			const pillW = 50, pillH = 14;
			const pillX = zp.x - pillW / 2;
			const pillY = by - 9;
			const myLvl = (window.gameState?.myStat?.level) || (window.gameState?.playerLevel) || 1;
			const isUnlocked = myLvl >= raid.requiredLevel;

			ctx.save();
			ctx.fillStyle = isUnlocked ? "rgba(180, 20, 20, 0.95)" : "rgba(35, 35, 35, 0.92)";
			ctx.strokeStyle = isUnlocked ? "rgba(255, 160, 40, 0.95)" : "rgba(140, 140, 140, 0.8)";
			ctx.lineWidth = 1.2;
			ctx.beginPath();
			if (ctx.roundRect) ctx.roundRect(pillX, pillY, pillW, pillH, 3);
			else ctx.rect(pillX, pillY, pillW, pillH);
			ctx.fill();
			ctx.stroke();

			ctx.fillStyle = isUnlocked ? "#ffd700" : "#bbbbbb";
			ctx.font = "bold 9px sans-serif";
			ctx.textAlign = "center";
			ctx.textBaseline = "middle";
			const reqLvl = raid.requiredLevel || 1;
			const displayLvl = raid.bossLevel || reqLvl;
			ctx.fillText(isUnlocked ? `⚔️ LV${displayLvl}` : `🔒 LV${reqLvl}`, zp.x, pillY + pillH / 2 + 0.5);
			ctx.restore();
		}
	}
	
	for (const src in Portals) {
		for (const tgt in Portals[src]) {
			const pInfo = Portals[src][tgt];
			const lPos = getLogicalPos(parseInt(src), pInfo.pos.x, pInfo.pos.z);
			if (!lPos) continue;
			
			if (pInfo.requiredQuestCode) {
				let isCompleted = false;
				if (gameState && gameState.zoneId && (gameState.zoneId % 10000) === parseInt(tgt)) {
					isCompleted = true;
				}
				if (window.lunCompletedQuests && window.lunCompletedQuests.has(pInfo.requiredQuestCode)) {
					isCompleted = true;
				}
				
				if (!isCompleted) {
					ctx.font = "10px sans-serif";
					ctx.fillStyle = "white";
					ctx.textAlign = "center";
					ctx.textBaseline = "middle";
					ctx.fillText("🔒", lPos.x, lPos.y);
					continue;
				}
			}
			
			ctx.fillStyle = "rgba(255, 200, 50, 0.9)";
			ctx.beginPath();
			ctx.arc(lPos.x, lPos.y, 2, 0, Math.PI * 2);
			ctx.fill();
		}
	}
	
	if (gameState && gameState.playerContainer && gameState.zoneId) {
		const pz = gameState.zoneId % 10000;
		if (zonePos[pz]) {
			const lPos = getLogicalPos(pz, gameState.playerContainer.position.x, gameState.playerContainer.position.z);
			if (lPos) {
				ctx.fillStyle = "red";
				ctx.strokeStyle = "white";
				ctx.lineWidth = 1;
				ctx.beginPath();
				ctx.arc(lPos.x, lPos.y, 4, 0, Math.PI * 2);
				ctx.fill();
				ctx.stroke();
			}
		}
	}
	
	mapUpdateFrame = requestAnimationFrame(updateMapLoop);
}

